"use client";

import { useState, useEffect, useRef } from "react";
import { useParams, useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Mic, MicOff, Send, Loader2, Volume2, VolumeX } from "lucide-react";
import api from "@/lib/api";
import DIdAvatar from "@/components/interview/DIdAvatar";
import { WebcamPreview } from "@/components/interview/WebcamPreview";
import { useWebSpeech } from "@/hooks/useWebSpeech";
import { avatarStateManager } from "@/lib/InterviewAvatarStateManager";
import { getFreshToken } from "@/lib/tokenManager";

export default function InterviewRoomPage() {
    const params = useParams();
    const router = useRouter();
    const interviewId = params.id as string;

    useEffect(() => {
        const redirectWithContext = async () => {
            const streamUrl = process.env.NEXT_PUBLIC_DID_STREAMING_URL || 'http://localhost:3001';
            try {
                // Get token using global token manager
                const token = await getFreshToken();

                // Fetch interview details to get applicationId
                const response = await api.get(`/interviews/${interviewId}`);
                const interviewData = response.data;
                const applicationId = interviewData.applicationId;

                // Build query params
                const params = new URLSearchParams({
                    interviewId: interviewId,
                    token: token || "",
                    applicationId: applicationId || ""
                });

                if (params.toString()) {
                    window.location.href = `${streamUrl}?${params.toString()}`;
                } else {
                    window.location.href = streamUrl;
                }
            } catch (err) {
                console.error("Failed to redirect with context:", err);
                // Fallback redirect if API fails
                window.location.href = streamUrl;
            }
        };

        if (interviewId) {
            redirectWithContext();
        }
    }, [interviewId]);

    const [interview, setInterview] = useState<any>(null);
    const [currentQuestion, setCurrentQuestion] = useState<any>(null);
    const [loading, setLoading] = useState(true);
    const [processing, setProcessing] = useState(false);
    const [messages, setMessages] = useState<any[]>([]);
    const [answerText, setAnswerText] = useState("");
    const [hasStarted, setHasStarted] = useState(false);
    const [isSpeaking, setIsSpeaking] = useState(false);

    const { transcript, interimTranscript, isListening, startListening, stopListening, resetTranscript } = useWebSpeech();

    const silenceTimerRef = useRef<NodeJS.Timeout | null>(null);
    const messagesEndRef = useRef<HTMLDivElement>(null);

    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    };

    useEffect(() => {
        scrollToBottom();
    }, [messages, answerText, interimTranscript]);

    useEffect(() => {
        if (transcript) {
            setAnswerText(transcript);
        }
    }, [transcript]);

    // HANDS-FREE AUTOMATION: Control microphone based on AI status
    useEffect(() => {
        if (hasStarted && !isSpeaking && !processing && !isListening) {
            console.log("Automation: AI stopped speaking. Starting microphone...");
            startListening();
        } else if ((isSpeaking || processing) && isListening) {
            console.log("Automation: AI speaking or processing. Stopping microphone...");
            stopListening();
        }
    }, [isSpeaking, processing, hasStarted, isListening]);

    // HANDS-FREE AUTOMATION: Silence detection (4s of inactivity triggers submission)
    useEffect(() => {
        if (silenceTimerRef.current) clearTimeout(silenceTimerRef.current);

        if (isListening && (transcript || interimTranscript) && !processing) {
            silenceTimerRef.current = setTimeout(() => {
                const finalAnswer = (transcript || answerText || interimTranscript).trim();
                // Only submit if we have meaningful content (> 5 chars)
                if (finalAnswer.length > 5) {
                    console.log("Automation: Silence detected. Submitting answer...");
                    handleAnswerSubmit(finalAnswer);
                }
            }, 4000);
        }

        return () => { if (silenceTimerRef.current) clearTimeout(silenceTimerRef.current); };
    }, [transcript, interimTranscript, isListening, processing, answerText]);

    useEffect(() => {
        const initSession = async () => {
            try {
                const response = await api.post(`/interviews/${interviewId}/start`);
                const data = response.data;

                if (data.status === 'completed') {
                    router.push(`/candidates/interviews/${interviewId}/report`);
                    return;
                }

                if (data.question) {
                    setCurrentQuestion(data.question);
                    setMessages(prev => {
                        if (prev.find(m => m.id === data.question.id)) return prev;
                        return [...prev, { role: 'ai', content: data.question.questionText, id: data.question.id }];
                    });
                }

                const details = await api.get(`/interviews/${interviewId}`);
                setInterview(details.data);

            } catch (error) {
                console.error("Failed to start session", error);
            } finally {
                setLoading(false);
            }
        };

        if (interviewId) {
            initSession();
        }

        return () => {
            stopListening();
            if (silenceTimerRef.current) clearTimeout(silenceTimerRef.current);
        };
    }, [interviewId]);

    const startInterview = async () => {
        setHasStarted(true);
        setProcessing(true);
        try {
            const response = await api.post(`/interviews/${interviewId}/start`);
            const data = response.data;
            if (data.question) {
                setCurrentQuestion(data.question);
                setMessages([{ role: 'ai', content: data.question.questionText, id: data.question.id }]);
            }
        } catch (err) {
            console.error("Start interview failed", err);
        } finally {
            setProcessing(false);
        }
    };

    const handleAnswerSubmit = async (textToSubmit?: string) => {
        const finalContent = textToSubmit || answerText;
        if (!finalContent.trim() || processing) return;

        setProcessing(true);
        stopListening();
        resetTranscript();
        setAnswerText("");

        const userMsg = { role: 'user', content: finalContent };
        setMessages(prev => [...prev, userMsg]);

        try {
            avatarStateManager.setTHINKING();
            const response = await api.post(`/interviews/${interviewId}/answer`, { answer: userMsg.content });
            const data = response.data;

            if (data.status === 'completed') {
                router.push(`/candidates/interviews/${interviewId}/report`);
                return;
            }

            if (data.question) {
                setCurrentQuestion(data.question);
                setMessages(prev => [...prev, { role: 'ai', content: data.question.questionText, id: data.question.id }]);
            }

        } catch (error) {
            console.error("Failed to submit answer", error);
            avatarStateManager.setIDLE();
        } finally {
            setProcessing(false);
        }
    };

    if (loading) {
        return <div className="flex h-screen items-center justify-center bg-slate-950"><Loader2 className="animate-spin h-8 w-8 text-blue-500" /></div>;
    }

    return (
        <div className="flex h-screen bg-[#020617] overflow-hidden relative font-sans text-slate-200">
            {!hasStarted && (
                <div className="absolute inset-0 z-50 bg-[#020617] flex flex-col items-center justify-center text-white p-4">
                    <div className="w-24 h-24 bg-blue-600 rounded-full flex items-center justify-center mb-8 animate-pulse shadow-[0_0_50px_rgba(37,99,235,0.4)]">
                        <Mic className="h-10 w-10 text-white" />
                    </div>
                    <h1 className="text-4xl font-bold mb-4 tracking-tight">AI Interview Room</h1>
                    <p className="text-slate-400 mb-12 max-w-sm text-center leading-relaxed text-lg">
                        Meet your interviewer, Alex. This session is automated and voice-activated for your convenience.
                    </p>
                    <Button onClick={startInterview} size="lg" className="bg-blue-600 hover:bg-blue-700 text-xl px-16 py-10 rounded-full shadow-2xl transition-all hover:scale-105 active:scale-95 border-b-4 border-blue-800">
                        Enter Interview
                    </Button>
                </div>
            )}

            {/* Stage Area (Avatar) */}
            <div className="flex-1 relative flex flex-col items-center justify-center p-12 bg-gradient-to-b from-[#020617] to-[#0f172a] overflow-hidden border-r border-white/5">
                {/* Header Overlay */}
                <div className="absolute top-8 left-12 right-12 flex justify-between items-start z-10">
                    <div className="flex flex-col gap-1">
                        <div className="flex items-center gap-3 bg-white/5 backdrop-blur-md border border-white/10 px-4 py-2 rounded-2xl">
                            <div className="w-2.5 h-2.5 bg-blue-500 rounded-full animate-pulse shadow-[0_0_10px_rgba(59,130,246,0.5)]" />
                            <span className="text-xs font-bold tracking-wider uppercase text-blue-100/80">Alex • Senior Interviewer</span>
                        </div>
                    </div>
                </div>

                {/* Avatar Frame */}
                <div className="relative h-full aspect-square rounded-[2.5rem] overflow-hidden shadow-[0_0_150px_rgba(0,0,0,0.8),0_0_50px_rgba(30,41,59,0.3)] border border-white/10 bg-black group flex items-center justify-center">
                    <DIdAvatar
                        interviewId={interviewId}
                        onStatusChange={(speaking) => setIsSpeaking(speaking)}
                        onStop={() => setIsSpeaking(false)}
                    />

                    {/* Status Overlays */}
                    <div className="absolute bottom-6 left-6 flex items-center gap-3 z-20">
                        <div className={`px-4 py-2 rounded-xl flex items-center gap-3 transition-all duration-700 backdrop-blur-xl border ${isListening ? 'bg-red-500/20 border-red-500/40 text-red-100' : 'bg-white/5 border-white/10 text-slate-400'}`}>
                            <div className={`h-2 w-2 rounded-full ${isListening ? 'bg-red-500 animate-ping' : 'bg-slate-600'}`} />
                            <span className="text-[10px] font-bold uppercase tracking-[0.2em]">
                                {processing ? 'Analyzing' : isListening ? 'Listening' : 'Ready'}
                            </span>
                        </div>
                    </div>

                    {/* Self Preview */}
                    <div className="absolute bottom-6 right-6 w-44 aspect-video shadow-2xl rounded-2xl overflow-hidden border border-white/10 ring-1 ring-white/20 transition-transform hover:scale-105 duration-300">
                        <WebcamPreview />
                    </div>
                </div>

                {/* Progress Bar (at the bottom of the stage) */}
                <div className="absolute bottom-12 left-24 right-24 h-1.5 bg-white/5 rounded-full overflow-hidden">
                    {isListening && !processing && (
                        <div className="h-full bg-blue-500 animate-progress w-full shadow-[0_0_15px_rgba(59,130,246,0.5)]" style={{ animationDuration: '4s' }} />
                    )}
                </div>
            </div>

            {/* Sidebar (Transcript) */}
            <div className="w-[400px] flex flex-col h-full bg-[#020617] border-l border-white/5">
                <div className="p-8 border-b border-white/5 flex flex-col gap-4">
                    <div className="flex justify-between items-center">
                        <div className="flex items-center gap-3">
                            <div className="h-8 w-8 bg-blue-600/20 rounded-lg flex items-center justify-center">
                                <Mic className="h-4 w-4 text-blue-500" />
                            </div>
                            <h2 className="text-sm font-bold text-white tracking-tight leading-none">Conversation</h2>
                        </div>
                        <Badge className="bg-white/5 border-white/10 text-white text-[10px] tracking-widest uppercase">Question {currentQuestion?.orderNumber || 1}</Badge>
                    </div>
                </div>

                <ScrollArea className="flex-1 px-6 py-8">
                    <div className="space-y-8 pb-20">
                        {messages.map((msg, idx) => (
                            <div key={idx} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'} animate-in fade-in slide-in-from-bottom-4 duration-500`}>
                                <div className={`flex items-center gap-2 mb-2 text-[9px] font-bold uppercase tracking-widest ${msg.role === 'user' ? 'text-blue-500' : 'text-slate-500'}`}>
                                    {msg.role === 'user' ? 'You' : 'Alex'}
                                </div>
                                <div className={`max-w-[90%] rounded-2xl p-4 text-sm font-medium leading-relaxed transition-all ${msg.role === 'user'
                                    ? 'bg-blue-600 text-white rounded-tr-none shadow-lg shadow-blue-900/20'
                                    : 'bg-white/5 border border-white/10 text-slate-300 rounded-tl-none'
                                    }`}>
                                    <p className="whitespace-pre-wrap">{msg.content}</p>
                                </div>
                            </div>
                        ))}

                        {(isListening || processing) && (
                            <div className="flex flex-col items-end animate-in fade-in slide-in-from-bottom-2 duration-300">
                                <div className={`max-w-[90%] w-full rounded-2xl p-4 border transition-all duration-500 rounded-tr-none ${processing ? 'bg-white/5 border-white/10 text-slate-500' :
                                    'bg-blue-600/10 border-blue-500/30 text-blue-100'}`}>
                                    <p className="text-sm italic leading-relaxed">
                                        {answerText || (interimTranscript ? `${interimTranscript}...` : "...")}
                                    </p>
                                    <div className="mt-3 flex items-center gap-2">
                                        <div className="flex gap-1">
                                            <div className="w-1 h-1 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
                                            <div className="w-1 h-1 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '150ms' }} />
                                            <div className="w-1 h-1 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '300ms' }} />
                                        </div>
                                        <span className="text-[9px] font-bold uppercase tracking-widest text-blue-500/70">
                                            {processing ? 'Processing' : 'Listening...'}
                                        </span>
                                    </div>
                                </div>
                            </div>
                        )}
                        <div ref={messagesEndRef} />
                    </div>
                </ScrollArea>
            </div>
        </div>
    );
}

"use client"

import { useEffect, useState } from "react"
import { motion } from "framer-motion"
import {
    Card,
    CardContent,
    CardHeader,
    CardTitle,
    CardDescription,
    CardFooter
} from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Video, Calendar, Clock, ArrowRight, Brain, Zap, Loader2 } from "lucide-react"
import Link from "next/link"
import api from "@/lib/api"
import { getFreshToken } from "@/lib/tokenManager"

export default function CandidateInterviewsPage() {
    const [interviews, setInterviews] = useState<any[]>([])
    const [applications, setApplications] = useState<any[]>([])
    const [loading, setLoading] = useState(true)
    const [startingId, setStartingId] = useState<string | null>(null)

    useEffect(() => {
        const fetchInterviews = async () => {
            try {
                const [interRes, appsRes] = await Promise.all([
                    api.get('/interviews'),
                    api.get('/candidates/applications')
                ])
                setInterviews(interRes.data)
                setApplications(appsRes.data)
            } catch (error) {
                console.error("Failed to fetch interviews or applications", error)
            } finally {
                setLoading(false)
            }
        }
        fetchInterviews()
    }, [])

    const handleStartInterview = async (applicationId: string) => {
        setStartingId(applicationId)
        try {
            const response = await api.post(`/interviews/start-with-app/${applicationId}`)
            const data = response.data
            // The response is { status, question } where question contains interviewId
            const interviewId = data.question?.interviewId || data.id
            const interviewToken = data.interviewToken
            if (!interviewId) {
                alert("Interview started but could not get interview ID. Please refresh and check Interviews page.")
                return
            }
            // Redirect to the standalone D-ID interview project with sync context
            const token = interviewToken || await getFreshToken();
            const streamUrl = process.env.NEXT_PUBLIC_DID_STREAMING_URL || 'http://localhost:3001';
            const backendUrl = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3003';
            window.location.href = `${streamUrl}?applicationId=${applicationId}&interviewId=${interviewId}&token=${token}&backendUrl=${encodeURIComponent(backendUrl)}`;
        } catch (error: any) {
            console.error("Failed to start interview", error)
            const msg = error?.response?.data?.message || "Failed to start interview. Please try again."
            alert(msg)
        } finally {
            setStartingId(null)
        }
    }

    const safeInterviews = Array.isArray(interviews) ? interviews : [];
    const upcomingInterviews = safeInterviews.filter(i => i.status === 'created' || i.status === 'in_progress')
    const pastInterviews = safeInterviews.filter(i => i.status === 'completed')

    const rejectedStatuses = ['rejected', 'rejected_ai', 'rejected_post_interview', 'selected', 'hold', 'completed']
    // Show interview opportunity for any active application that doesn't have an interview session yet
    const eligibleApplications = Array.isArray(applications)
        ? applications.filter(app =>
            !rejectedStatuses.includes(app.status.toLowerCase()) &&
            !safeInterviews.find(i => i.applicationId === app.id)
        )
        : []

    if (loading) return (
        <div className="flex items-center justify-center p-20">
            <Loader2 className="h-8 w-8 animate-spin text-primary" />
        </div>
    )

    return (
        <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
            className="space-y-8"
        >
            <div className="flex flex-col gap-2">
                <h1 className="text-3xl font-bold tracking-tight">Interviews</h1>
                <p className="text-muted-foreground">Prepare and participate in your scheduled AI video interviews.</p>
            </div>

            {/* New Invitations Section */}
            {eligibleApplications.length > 0 && (
                <section className="space-y-4">
                    <div className="flex items-center gap-2">
                        <Zap className="h-5 w-5 text-yellow-500 fill-yellow-500" />
                        <h2 className="text-xl font-bold">Interview Opportunities</h2>
                    </div>
                    <div className="grid gap-6 md:grid-cols-2">
                        {eligibleApplications.map((app) => (
                            <motion.div key={app.id} initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }}>
                                <Card className="border-none shadow-lg rounded-2xl overflow-hidden bg-gradient-to-br from-primary/10 via-primary/5 to-transparent border-l-4 border-primary">
                                    <CardHeader className="pb-2">
                                        <div className="flex justify-between items-start">
                                            <Badge className="bg-yellow-500 text-white rounded-full px-3 font-bold border-none shadow-sm">
                                                ELIGIBLE
                                            </Badge>
                                            <Brain className="h-5 w-5 text-primary opacity-50" />
                                        </div>
                                        <CardTitle className="pt-2 text-xl">{app.job?.title || "Role"}</CardTitle>
                                        <CardDescription className="font-bold text-primary">{app.job?.department || "Company"}</CardDescription>
                                    </CardHeader>
                                    <CardContent className="py-4">
                                        <p className="text-sm text-foreground/70 leading-relaxed">
                                            Great news! Your profile matched the requirements. You are invited to take the AI interview for this position.
                                        </p>
                                    </CardContent>
                                    <CardFooter className="pt-2 pb-6">
                                        <Button
                                            onClick={() => handleStartInterview(app.id)}
                                            disabled={startingId === app.id}
                                            className="w-full rounded-xl h-12 font-bold bg-primary hover:bg-primary/90 shadow-xl shadow-primary/30 transition-all gap-2"
                                        >
                                            {startingId === app.id ? (
                                                <Loader2 className="h-5 w-5 animate-spin" />
                                            ) : (
                                                <>
                                                    Start AI Interview
                                                    <ArrowRight className="h-5 w-5" />
                                                </>
                                            )}
                                        </Button>
                                    </CardFooter>
                                </Card>
                            </motion.div>
                        ))}
                    </div>
                </section>
            )}

            <section className="space-y-4">
                <h2 className="text-xl font-bold">Upcoming Sessions</h2>
                {upcomingInterviews.length > 0 ? (
                    <div className="grid gap-6 md:grid-cols-2">
                        {upcomingInterviews.map((interview) => (
                            <motion.div key={interview.id} whileHover={{ y: -5 }} transition={{ duration: 0.2 }}>
                                <Card className="border-none shadow-sm rounded-2xl overflow-hidden ring-1 ring-primary/20">
                                    <CardHeader className="bg-primary/5 pb-4">
                                        <div className="flex items-center justify-between">
                                            <Badge className="bg-primary text-primary-foreground rounded-full px-3">
                                                {interview.status}
                                            </Badge>
                                            <div className="flex items-center gap-1 text-xs font-bold text-primary uppercase tracking-wider">
                                                <Video className="h-3 w-3" />
                                                Video
                                            </div>
                                        </div>
                                        <CardTitle className="pt-2">{interview.job?.title || "Role"}</CardTitle>
                                        <CardDescription className="font-semibold text-primary">{interview.job?.department || "Company"}</CardDescription>
                                    </CardHeader>
                                    <CardContent className="pt-6 space-y-4">
                                        <div className="flex items-center gap-3 text-sm">
                                            <div className="p-2 rounded-lg bg-muted text-muted-foreground">
                                                <Calendar className="h-4 w-4" />
                                            </div>
                                            <span>{new Date(interview.createdAt).toLocaleDateString()}</span>
                                        </div>
                                        <div className="flex items-center gap-3 text-sm">
                                            <div className="p-2 rounded-lg bg-muted text-muted-foreground">
                                                <Clock className="h-4 w-4" />
                                            </div>
                                            <span>Flexible Time</span>
                                        </div>
                                    </CardContent>
                                    <CardFooter className="bg-muted/30 pt-4 pb-4">
                                        <Button
                                            onClick={async () => {
                                                try {
                                                    const response = await api.get(`/interviews/${interview.id}`);
                                                    const detailedInterview = response.data;
                                                    const token = detailedInterview.interviewToken || await getFreshToken() || '';
                                                    const streamUrl = process.env.NEXT_PUBLIC_DID_STREAMING_URL || 'http://localhost:3001';
                                                    const backendUrl = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3003';
                                                    window.location.href = `${streamUrl}?applicationId=${interview.applicationId}&interviewId=${interview.id}&token=${token}&backendUrl=${encodeURIComponent(backendUrl)}`;
                                                } catch (err) {
                                                    console.error("Failed to join interview", err);
                                                    alert("Failed to join interview. Please try again.");
                                                }
                                            }}
                                            className="w-full rounded-xl h-11 font-bold shadow-lg shadow-primary/20 hover:shadow-primary/30 transition-all">
                                            Join Interview Room
                                            <ArrowRight className="ml-2 h-4 w-4 font-bold" />
                                        </Button>
                                    </CardFooter>
                                </Card>
                            </motion.div>
                        ))}
                    </div>
                ) : (
                    <div className="flex flex-col items-center justify-center p-12 bg-muted/10 rounded-2xl border-2 border-dashed border-muted">
                        <Video className="h-12 w-12 text-muted-foreground mb-4" />
                        <p className="text-lg font-semibold">No upcoming interviews</p>
                        <p className="text-sm text-muted-foreground">New scheduled sessions will appear here.</p>
                    </div>
                )}
            </section>

            <section className="space-y-4">
                <h2 className="text-xl font-bold">Past Assessments</h2>
                <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
                    {pastInterviews.map((interview) => (
                        <Card key={interview.id} className="border-none shadow-sm rounded-2xl hover:shadow-md transition-all">
                            <CardHeader className="pb-2">
                                <div className="flex justify-between items-start">
                                    <div className="h-10 w-10 rounded-xl bg-muted flex items-center justify-center font-bold text-muted-foreground">
                                        {interview.job?.department?.[0] || 'J'}
                                    </div>
                                    <Badge variant="secondary" className="rounded-full font-bold text-[10px] uppercase">
                                        {interview.status}
                                    </Badge>
                                </div>
                                <CardTitle className="text-base pt-3">{interview.job?.title}</CardTitle>
                                <CardDescription>{interview.job?.department}</CardDescription>
                            </CardHeader>
                            <CardContent className="pb-4">
                                <div className="flex items-center justify-between">
                                    <div className="flex items-center gap-2">
                                        <Brain className="h-4 w-4 text-primary" />
                                        <span className="text-sm font-bold">{interview.score} / 100</span>
                                    </div>
                                    <div className="flex items-center gap-2 text-xs text-muted-foreground">
                                        <Calendar className="h-3 w-3" />
                                        {new Date(interview.createdAt).toLocaleDateString()}
                                    </div>
                                </div>
                                <div className="mt-3 h-1.5 w-full bg-muted rounded-full overflow-hidden">
                                    <div
                                        className="h-full bg-primary rounded-full"
                                        style={{ width: `${interview.score}%` }}
                                    />
                                </div>
                            </CardContent>
                            <CardFooter className="pt-0">
                                <Button variant="ghost" size="sm" className="w-full rounded-lg text-primary hover:bg-primary/5 hover:text-primary font-bold" asChild>
                                    <Link href="/candidate/reports">
                                        View Evaluation Detail
                                    </Link>
                                </Button>
                            </CardFooter>
                        </Card>
                    ))}
                </div>
            </section>
        </motion.div>
    )
}

"use client"

import { useState, useEffect } from "react"
import { motion } from "framer-motion"
import {
    Search,
    MapPin,
    Briefcase,
    Building2,
    Clock,
    ArrowRight,
    Filter,
    CheckCircle2,
    Loader2
} from "lucide-react"
import { Input } from "@/components/ui/input"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { Card, CardContent, CardHeader, CardTitle, CardDescription, CardFooter } from "@/components/ui/card"
import api from "@/lib/api"
import { JobDetailsDialog } from "@/components/jobs/JobDetailsDialog"

interface Job {
    id: string
    title: string
    description: string
    department?: string
    location?: string
    type?: string
    salaryRange?: string
    skills: string[]
    createdAt: string
}

export default function FindJobsPage() {
    const [jobs, setJobs] = useState<Job[]>([])
    const [loading, setLoading] = useState(true)
    const [search, setSearch] = useState("")
    const [applying, setApplying] = useState<string | null>(null)
    const [appliedJobs, setAppliedJobs] = useState<string[]>([])

    useEffect(() => {
        const fetchData = async () => {
            try {
                const [jobsRes, appsRes] = await Promise.all([
                    api.get('/jobs'),
                    api.get('/candidates/applications')
                ])
                const safeJobs = Array.isArray(jobsRes.data) ? jobsRes.data : [];
                setJobs(safeJobs)
                const safeApps = Array.isArray(appsRes.data) ? appsRes.data : [];
                setAppliedJobs(safeApps.map((app: any) => app.jobId))
            } catch (error) {
                console.error("Failed to fetch jobs", error)
            } finally {
                setLoading(false)
            }
        }
        fetchData()
    }, [])

    const handleApply = async (jobId: string) => {
        setApplying(jobId)
        try {
            await api.post(`/candidates/apply/${jobId}`)
            setAppliedJobs(prev => [...prev, jobId])
            alert("Application submitted successfully!")
        } catch (error) {
            console.error("Failed to apply", error)
            alert("Failed to submit application. You might have already applied for this role.")
        } finally {
            setApplying(null)
        }
    }

    const filteredJobs = jobs.filter(job =>
        job.title.toLowerCase().includes(search.toLowerCase()) ||
        job.department?.toLowerCase().includes(search.toLowerCase()) ||
        (job.skills && job.skills.some(s => s.toLowerCase().includes(search.toLowerCase())))
    )

    if (loading) return (
        <div className="flex items-center justify-center p-20">
            <Loader2 className="h-8 w-8 animate-spin text-primary" />
        </div>
    )

    return (
        <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="space-y-8"
        >
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div className="space-y-1">
                    <h1 className="text-3xl font-bold tracking-tight">Open Opportunities</h1>
                    <p className="text-muted-foreground">Find the perfect role that matches your skills and career goals.</p>
                </div>
                <div className="flex items-center gap-2">
                    <div className="relative w-full md:w-[300px]">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                        <Input
                            placeholder="Search jobs, skills, or departments..."
                            className="pl-9 bg-muted/50 border-none rounded-xl h-11"
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                        />
                    </div>
                </div>
            </div>

            <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
                {filteredJobs.length === 0 ? (
                    <div className="col-span-full text-center py-20 bg-muted/10 rounded-3xl border-2 border-dashed border-muted">
                        <Briefcase className="h-12 w-12 text-muted-foreground mx-auto mb-4 opacity-20" />
                        <p className="font-semibold text-xl">No jobs found matching your criteria.</p>
                        <p className="text-muted-foreground">Try adjusting your search or check back later.</p>
                    </div>
                ) : filteredJobs.map((job, index) => (
                    <motion.div
                        key={job.id}
                        initial={{ opacity: 0, scale: 0.95 }}
                        animate={{ opacity: 1, scale: 1 }}
                        transition={{ delay: index * 0.05 }}
                    >
                        <Card className="h-full border-none shadow-sm hover:shadow-xl transition-all duration-300 rounded-3xl overflow-hidden group flex flex-col">
                            <CardHeader className="pb-4">
                                <div className="flex justify-between items-start mb-2">
                                    <div className="p-3 rounded-2xl bg-primary/10 text-primary group-hover:bg-primary group-hover:text-white transition-colors duration-300">
                                        <Briefcase className="h-6 w-6" />
                                    </div>
                                    <Badge variant="outline" className="rounded-full bg-muted/50 border-none px-3 py-1 font-bold text-[10px] uppercase">
                                        {job.type || "Full Time"}
                                    </Badge>
                                </div>
                                <JobDetailsDialog
                                    job={job}
                                    isApplied={appliedJobs.includes(job.id)}
                                    onApply={handleApply}
                                    isApplying={applying === job.id}
                                    trigger={
                                        <CardTitle className="text-xl font-bold group-hover:text-primary transition-colors cursor-pointer hover:underline decoration-primary/30 underline-offset-4">
                                            {job.title}
                                        </CardTitle>
                                    }
                                />
                                <CardDescription className="font-semibold text-primary">{job.department || "Engineering"}</CardDescription>
                            </CardHeader>

                            <CardContent className="flex-1 space-y-4">
                                <div className="flex flex-wrap gap-4 text-sm text-muted-foreground">
                                    <div className="flex items-center gap-1.5">
                                        <MapPin className="h-4 w-4" />
                                        {job.location || "Remote"}
                                    </div>
                                    <div className="flex items-center gap-1.5">
                                        <Clock className="h-4 w-4" />
                                        {new Date(job.createdAt).toLocaleDateString()}
                                    </div>
                                </div>
                                <JobDetailsDialog
                                    job={job}
                                    isApplied={appliedJobs.includes(job.id)}
                                    onApply={handleApply}
                                    isApplying={applying === job.id}
                                    trigger={
                                        <div className="space-y-2 cursor-pointer group/desc">
                                            <p className="text-sm line-clamp-3 text-muted-foreground leading-relaxed group-hover/desc:text-foreground transition-colors">
                                                {job.description}
                                            </p>
                                        </div>
                                    }
                                />
                                <div className="flex flex-wrap gap-2 pt-2">
                                    {job.skills?.slice(0, 3).map(skill => (
                                        <Badge key={skill} variant="outline" className="text-[10px] bg-muted/30 border-none rounded-full px-2 py-0.5 font-bold">
                                            {skill}
                                        </Badge>
                                    ))}
                                    {(job.skills?.length || 0) > 3 && (
                                        <span className="text-[10px] text-muted-foreground font-bold">+{(job.skills?.length || 0) - 3}</span>
                                    )}
                                </div>
                            </CardContent>

                            <CardFooter className="pt-4 border-t border-muted/50 bg-muted/10 items-center justify-between gap-2">
                                <JobDetailsDialog
                                    job={job}
                                    isApplied={appliedJobs.includes(job.id)}
                                    onApply={handleApply}
                                    isApplying={applying === job.id}
                                    trigger={
                                        <Button variant="ghost" size="sm" className="font-bold text-xs rounded-xl hover:bg-primary/5">
                                            Full Details
                                        </Button>
                                    }
                                />
                                {appliedJobs.includes(job.id) ? (
                                    <Button disabled className="flex-1 rounded-2xl h-11 bg-green-500/10 text-green-600 border-none hover:bg-green-500/10 font-bold gap-2">
                                        <CheckCircle2 className="h-4 w-4" />
                                        Applied
                                    </Button>
                                ) : (
                                    <Button
                                        className="flex-1 rounded-2xl h-11 font-bold shadow-lg shadow-primary/20 group-hover:shadow-primary/40 transition-all gap-2"
                                        onClick={() => handleApply(job.id)}
                                        disabled={applying === job.id}
                                    >
                                        {applying === job.id ? <Loader2 className="h-4 w-4 animate-spin" /> : <ArrowRight className="h-4 w-4" />}
                                        Apply
                                    </Button>
                                )}
                            </CardFooter>
                        </Card>
                    </motion.div>
                ))}
            </div>
        </motion.div>
    )
}

"use client"

import { motion } from "framer-motion"
import {
    Card,
    CardContent,
    CardHeader,
    CardTitle,
    CardDescription,
    CardFooter
} from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"
import { useUser } from "@clerk/nextjs"
import {
    User,
    Mail,
    Linkedin,
    Globe,
    FileText,
    Plus,
    X,
    Briefcase,
    GraduationCap,
    CheckCircle2,
    Loader2,
    MapPin,
    Camera,
    Calendar
} from "lucide-react"
import { useEffect, useState, useRef } from "react"
import api from "@/lib/api"
import Link from "next/link"
import { toast } from "sonner"
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog"

export default function CandidateProfilePage() {
    const { user, isLoaded } = useUser()
    const [profile, setProfile] = useState<any>(null)
    const [loading, setLoading] = useState(true)
    const [saving, setSaving] = useState(false)
    const [uploading, setUploading] = useState(false)
    const [resumeUploading, setResumeUploading] = useState(false)
    const [stats, setStats] = useState<any>(null)
    const fileInputRef = useRef<HTMLInputElement>(null)
    const resumeFileInputRef = useRef<HTMLInputElement>(null)

    // Form State
    const [formData, setFormData] = useState({
        firstName: "",
        lastName: "",
        title: "",
        bio: "",
        location: "",
        linkedinUrl: "",
        portfolioUrl: "",
        avatarUrl: "",
        resumeUrl: "",
        skills: [] as string[]
    })
    const [experiences, setExperiences] = useState<any[]>([])
    const [experienceForm, setExperienceForm] = useState({
        employer: "",
        role: "",
        startDate: "",
        endDate: "",
        description: "",
        isCurrent: false
    })
    const [isAddingExperience, setIsAddingExperience] = useState(false)
    const [editingExpId, setEditingExpId] = useState<string | null>(null)

    useEffect(() => {
        const fetchData = async () => {
            try {
                const profileRes = await api.get('/candidates/profile')
                const data = profileRes.data
                setProfile(data)
                setFormData({
                    firstName: data.user?.firstName || "",
                    lastName: data.user?.lastName || "",
                    title: data.title || "",
                    bio: data.bio || "",
                    location: data.location || "Remote",
                    linkedinUrl: data.linkedinUrl || "",
                    portfolioUrl: data.portfolioUrl || "",
                    avatarUrl: data.user?.avatarUrl || "",
                    resumeUrl: data.resumeUrl || "",
                    skills: data.skills || []
                })
            } catch (error) {
                console.error("Failed to fetch profile", error)
            }

            try {
                const statsRes = await api.get('/candidates/stats')
                setStats(statsRes.data)
            } catch (error) {
                console.error("Failed to fetch stats", error)
            }

            try {
                const expRes = await api.get('/candidates/experiences')
                setExperiences(expRes.data)
            } catch (error) {
                console.error("Failed to fetch experiences", error)
            }

            setLoading(false)
        }
        fetchData()
    }, [])

    const fetchStats = async () => {
        try {
            const statsRes = await api.get('/candidates/stats')
            setStats(statsRes.data)
        } catch (error) {
            console.error("Failed to fetch stats", error)
        }
    }

    const handleSave = async () => {
        console.log("Saving profile, auth context:", { user })
        setSaving(true)
        try {
            await api.post('/candidates/profile', formData)
            await fetchStats() // Refresh stats after save

            // Clerk user update (optional, but keep UI in sync)
            if (user) {
                await user.update({
                    firstName: formData.firstName,
                    lastName: formData.lastName,
                });
            }

            alert("Profile saved successfully!")
        } catch (error) {
            console.error("Failed to save profile", error)
            alert("Error saving profile. Please check console.")
        } finally {
            setSaving(false)
        }
    }

    const handleAvatarUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0]
        if (!file) return

        setUploading(true)
        const uploadData = new FormData()
        uploadData.append('file', file)

        try {
            const response = await api.post('/candidates/avatar-upload', uploadData, {
                headers: { 'Content-Type': 'multipart/form-data' }
            })
            const newUrl = response.data.avatarUrl
            setFormData({ ...formData, avatarUrl: newUrl })

            alert("Avatar uploaded successfully!")
        } catch (error) {
            console.error("Upload failed", error)
            alert("Failed to upload avatar")
        } finally {
            setUploading(false)
        }
    }

    const handleResumeUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0]
        if (!file) return

        if (file.type !== 'application/pdf') {
            alert("Please upload a PDF file")
            return
        }

        setResumeUploading(true)
        const uploadData = new FormData()
        uploadData.append('file', file)

        try {
            const response = await api.post('/candidates/resume-upload', uploadData, {
                headers: { 'Content-Type': 'multipart/form-data' }
            })
            const updatedProfile = response.data
            setFormData({
                ...formData,
                resumeUrl: updatedProfile.resumeUrl,
                skills: updatedProfile.skills || formData.skills
            })
            await fetchStats() // Refresh stats after resume parsing
            alert("Resume uploaded and parsed successfully!")
        } catch (error) {
            console.error("Resume upload failed", error)
            alert("Failed to upload resume. Please ensure it is a valid PDF.")
        } finally {
            setResumeUploading(false)
        }
    }

    const fetchExperiences = async () => {
        try {
            const response = await api.get('/candidates/experiences')
            setExperiences(response.data)
        } catch (error) {
            console.error("Failed to fetch experiences", error)
        }
    }

    const handleAddExperience = async () => {
        // Validation
        if (!experienceForm.employer.trim() || !experienceForm.role.trim() || !experienceForm.startDate) {
            toast.error("Please fill in company, role, and start date");
            return;
        }

        setSaving(true)
        try {
            if (editingExpId) {
                await api.patch(`/candidates/experiences/${editingExpId}`, experienceForm)
            } else {
                await api.post('/candidates/experiences', experienceForm)
            }
            toast.success(editingExpId ? "Experience updated" : "Experience added")
            setIsAddingExperience(false)
            setEditingExpId(null)
            setExperienceForm({ employer: "", role: "", startDate: "", endDate: "", description: "", isCurrent: false })
            fetchExperiences()
            fetchStats()
        } catch (error) {
            console.error("Failed to save experience", error)
            toast.error("Failed to save experience")
        } finally {
            setSaving(false)
        }
    }

    const handleDeleteExperience = async (id: string) => {
        if (!confirm("Are you sure you want to delete this experience?")) return
        try {
            await api.delete(`/candidates/experiences/${id}`)
            toast.success("Experience deleted")
            fetchExperiences()
            fetchStats()
        } catch (error) {
            console.error("Failed to delete experience", error)
            toast.error("Failed to delete experience")
        }
    }

    const addSkill = (skill: string) => {
        if (skill && !formData.skills.includes(skill)) {
            setFormData({ ...formData, skills: [...formData.skills, skill] })
        }
    }

    const removeSkill = (skillToRemove: string) => {
        setFormData({ ...formData, skills: formData.skills.filter(s => s !== skillToRemove) })
    }

    if (loading) return (
        <div className="flex items-center justify-center p-20">
            <Loader2 className="h-8 w-8 animate-spin text-primary" />
        </div>
    )

    return (
        <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
            className="grid gap-8 lg:grid-cols-3"
        >
            {/* Left: Sidebar-like Profile Card */}
            <div className="space-y-6">
                <Card className="border-none shadow-sm rounded-3xl overflow-hidden bg-card p-8 text-center space-y-6">
                    <div
                        className="relative mx-auto h-32 w-32 rounded-3xl overflow-hidden ring-4 ring-primary/10 cursor-pointer group"
                        onClick={() => fileInputRef.current?.click()}
                    >
                        <div className="w-full h-full bg-primary/10 flex items-center justify-center">
                            {uploading ? (
                                <Loader2 className="h-8 w-8 animate-spin text-primary" />
                            ) : formData.avatarUrl ? (
                                <img
                                    src={formData.avatarUrl}
                                    alt="Avatar"
                                    className="w-full h-full object-cover"
                                    onError={(e) => {
                                        e.currentTarget.style.display = 'none';
                                        // Show the icon instead
                                        const parent = e.currentTarget.parentElement;
                                        if (parent) {
                                            const icon = document.createElement('div');
                                            icon.className = 'flex items-center justify-center h-full w-full';
                                            icon.innerHTML = '<svg ...></svg>'; // Simplified, better to handle in state
                                        }
                                    }}
                                />
                            ) : (
                                <User className="h-16 w-16 text-primary" />
                            )}
                        </div>
                        <div className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                            <Camera className="h-8 w-8 text-white" />
                        </div>
                    </div>
                    <input
                        type="file"
                        ref={fileInputRef}
                        className="hidden"
                        accept="image/*"
                        onChange={handleAvatarUpload}
                    />
                    <div>
                        <h2 className="text-2xl font-bold">{formData.firstName} {formData.lastName}</h2>
                        <p className="text-sm text-primary font-semibold">{formData.title || "Career Profile"}</p>
                    </div>

                    <div className="space-y-4">
                        <div className="flex flex-col gap-2">
                            <div className="flex justify-between text-xs font-bold uppercase tracking-wider text-muted-foreground">
                                <span>Profile Strength</span>
                                <span>{stats?.profileStrength || 0}%</span>
                            </div>
                            <div className="h-2 w-full bg-muted rounded-full">
                                <motion.div
                                    initial={{ width: 0 }}
                                    animate={{ width: `${stats?.profileStrength || 0}%` }}
                                    className="h-full bg-primary rounded-full transition-all duration-500"
                                />
                            </div>
                        </div>
                        <p className="text-xs text-muted-foreground italic">
                            {stats?.profileStrength < 100
                                ? `Improve your profile by adding ${!formData.portfolioUrl ? "a portfolio link" : "more details"} to reach 100%.`
                                : "Your profile is fully complete! Excellent work."}
                        </p>
                    </div>

                    <hr className="border-muted/50" />

                    <div className="space-y-3">
                        <Button
                            variant="outline"
                            className="w-full rounded-xl gap-2 font-bold h-11"
                            disabled={resumeUploading}
                            onClick={() => resumeFileInputRef.current?.click()}
                        >
                            {resumeUploading ? (
                                <Loader2 className="h-4 w-4 animate-spin" />
                            ) : (
                                <FileText className="h-4 w-4" />
                            )}
                            {resumeUploading ? "Uploading..." : "Update Resume (PDF)"}
                        </Button>
                        <input
                            type="file"
                            ref={resumeFileInputRef}
                            className="hidden"
                            accept="application/pdf"
                            onChange={handleResumeUpload}
                        />
                        <Button className="w-full rounded-xl gap-2 font-bold h-11 shadow-lg shadow-primary/20" asChild>
                            <Link href={`/candidates/view/${profile?.id}`}>
                                View Public Profile
                            </Link>
                        </Button>
                    </div>
                </Card>

                <Card className="border-none shadow-sm rounded-3xl p-8 space-y-6">
                    <h3 className="text-lg font-bold">Social & Links</h3>
                    <div className="space-y-4">
                        <div className="space-y-2">
                            <Label className="text-xs font-bold text-muted-foreground">LinkedIn</Label>
                            <div className="relative">
                                <Linkedin className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                                <Input
                                    value={formData.linkedinUrl}
                                    onChange={(e) => setFormData({ ...formData, linkedinUrl: e.target.value })}
                                    placeholder="linkedin.com/in/username"
                                    className="pl-9 bg-muted/50 border-none rounded-xl h-11"
                                />
                            </div>
                        </div>
                        <div className="space-y-2">
                            <Label className="text-xs font-bold text-muted-foreground">Portfolio</Label>
                            <div className="relative">
                                <Globe className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                                <Input
                                    value={formData.portfolioUrl}
                                    onChange={(e) => setFormData({ ...formData, portfolioUrl: e.target.value })}
                                    placeholder="portfolio.com"
                                    className="pl-9 bg-muted/50 border-none rounded-xl h-11"
                                />
                            </div>
                        </div>
                    </div>
                </Card>
            </div>

            {/* Right: Main Content */}
            <div className="lg:col-span-2 space-y-6">
                <Card className="border-none shadow-sm rounded-3xl p-8 space-y-8">
                    <div>
                        <h3 className="text-xl font-bold">Personal Information</h3>
                        <p className="text-sm text-muted-foreground">Details shown to recruiters when they view your profile.</p>
                    </div>

                    <div className="grid gap-6 md:grid-cols-2">
                        <div className="space-y-2">
                            <Label>First Name</Label>
                            <Input
                                value={formData.firstName}
                                onChange={(e) => setFormData({ ...formData, firstName: e.target.value })}
                                className="bg-muted/50 border-none h-11 rounded-xl"
                            />
                        </div>
                        <div className="space-y-2">
                            <Label>Last Name</Label>
                            <Input
                                value={formData.lastName}
                                onChange={(e) => setFormData({ ...formData, lastName: e.target.value })}
                                className="bg-muted/50 border-none h-11 rounded-xl"
                            />
                        </div>
                        <div className="space-y-2">
                            <Label>Professional Title</Label>
                            <Input
                                value={formData.title}
                                onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                                placeholder="e.g. Senior Product Designer"
                                className="bg-muted/50 border-none h-11 rounded-xl"
                            />
                        </div>
                        <div className="space-y-2">
                            <Label>Avatar URL</Label>
                            <Input
                                value={formData.avatarUrl}
                                onChange={(e) => setFormData({ ...formData, avatarUrl: e.target.value })}
                                placeholder="https://example.com/photo.jpg"
                                className="bg-muted/50 border-none h-11 rounded-xl"
                            />
                        </div>
                        <div className="space-y-2">
                            <Label>Location</Label>
                            <div className="relative">
                                <MapPin className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                                <Input
                                    value={formData.location}
                                    onChange={(e) => setFormData({ ...formData, location: e.target.value })}
                                    className="pl-9 bg-muted/50 border-none h-11 rounded-xl"
                                />
                            </div>
                        </div>
                        <div className="space-y-2 md:col-span-2">
                            <Label>Professional Bio</Label>
                            <Textarea
                                value={formData.bio}
                                onChange={(e) => setFormData({ ...formData, bio: e.target.value })}
                                placeholder="Tell us about your experience and what you're looking for..."
                                className="bg-muted/50 border-none rounded-2xl min-h-[120px]"
                            />
                        </div>
                    </div>
                </Card>

                <Card className="border-none shadow-sm rounded-3xl p-8 space-y-6">
                    <div className="flex items-center justify-between">
                        <h3 className="text-xl font-bold">Work Experience</h3>
                        <Button
                            variant="outline"
                            className="rounded-xl gap-2 font-bold"
                            onClick={() => {
                                setEditingExpId(null)
                                setExperienceForm({ employer: "", role: "", startDate: "", endDate: "", description: "", isCurrent: false })
                                setIsAddingExperience(true)
                            }}
                        >
                            <Plus className="h-4 w-4" /> Add Experience
                        </Button>
                    </div>

                    <div className="space-y-4">
                        {experiences.map((exp) => (
                            <div key={exp.id} className="p-6 rounded-2xl bg-slate-50 dark:bg-card/50 border border-slate-100 dark:border-border group relative">
                                <div className="flex justify-between items-start">
                                    <div className="flex gap-4">
                                        <div className="h-12 w-12 rounded-xl bg-white dark:bg-card shadow-sm flex items-center justify-center border border-slate-100 dark:border-border">
                                            <Briefcase className="h-6 w-6 text-primary" />
                                        </div>
                                        <div>
                                            <h4 className="font-bold text-lg">{exp.role}</h4>
                                            <p className="text-primary font-bold">{exp.employer}</p>
                                            <p className="text-xs text-muted-foreground font-medium flex items-center gap-1 mt-1">
                                                <Calendar className="h-3 w-3" />
                                                {new Date(exp.startDate).toLocaleDateString()} - {exp.isCurrent ? "Present" : new Date(exp.endDate).toLocaleDateString()}
                                            </p>
                                        </div>
                                    </div>
                                    <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                        <Button
                                            variant="ghost"
                                            size="sm"
                                            className="h-8 w-8 p-0 rounded-lg hover:bg-white"
                                            onClick={() => {
                                                setEditingExpId(exp.id)
                                                setExperienceForm({
                                                    employer: exp.employer,
                                                    role: exp.role,
                                                    startDate: exp.startDate.split('T')[0],
                                                    endDate: exp.endDate ? exp.endDate.split('T')[0] : "",
                                                    description: exp.description || "",
                                                    isCurrent: exp.isCurrent
                                                })
                                                setIsAddingExperience(true)
                                            }}
                                        >
                                            <Globe className="h-4 w-4" />
                                        </Button>
                                        <Button
                                            variant="ghost"
                                            size="sm"
                                            className="h-8 w-8 p-0 rounded-lg hover:bg-white text-destructive"
                                            onClick={() => handleDeleteExperience(exp.id)}
                                        >
                                            <X className="h-4 w-4" />
                                        </Button>
                                    </div>
                                </div>
                                {exp.description && (
                                    <p className="mt-4 text-sm text-slate-600 dark:text-muted-foreground font-medium leading-relaxed">
                                        {exp.description}
                                    </p>
                                )}
                            </div>
                        ))}
                    </div>
                </Card>

                {/* Experience Dialog */}
                <Dialog open={isAddingExperience} onOpenChange={setIsAddingExperience}>
                    <DialogContent className="sm:max-w-[500px] rounded-3xl border-none p-8">
                        <DialogHeader>
                            <DialogTitle className="text-2xl font-bold">{editingExpId ? "Edit Experience" : "Add Experience"}</DialogTitle>
                        </DialogHeader>
                        <div className="grid gap-6 py-4">
                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <Label>Employer / Company</Label>
                                    <Input
                                        className="bg-muted/50 border-none h-11 rounded-xl"
                                        value={experienceForm.employer}
                                        onChange={(e) => setExperienceForm({ ...experienceForm, employer: e.target.value })}
                                        placeholder="e.g. Acme Corp"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <Label>Role / Title</Label>
                                    <Input
                                        className="bg-muted/50 border-none h-11 rounded-xl"
                                        value={experienceForm.role}
                                        onChange={(e) => setExperienceForm({ ...experienceForm, role: e.target.value })}
                                        placeholder="e.g. Frontend Engineer"
                                    />
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <Label>Start Date</Label>
                                    <Input
                                        type="date"
                                        className="bg-muted/50 border-none h-11 rounded-xl"
                                        value={experienceForm.startDate}
                                        onChange={(e) => setExperienceForm({ ...experienceForm, startDate: e.target.value })}
                                    />
                                </div>
                                <div className="space-y-2">
                                    <Label>End Date</Label>
                                    <Input
                                        type="date"
                                        className="bg-muted/50 border-none h-11 rounded-xl"
                                        value={experienceForm.endDate}
                                        onChange={(e) => setExperienceForm({ ...experienceForm, endDate: e.target.value })}
                                        disabled={experienceForm.isCurrent}
                                    />
                                </div>
                            </div>
                            <div className="flex items-center gap-2">
                                <input
                                    type="checkbox"
                                    id="isCurrent"
                                    checked={experienceForm.isCurrent}
                                    onChange={(e) => setExperienceForm({ ...experienceForm, isCurrent: e.target.checked })}
                                />
                                <Label htmlFor="isCurrent" className="text-sm font-medium">I am currently working in this role</Label>
                            </div>
                            <div className="space-y-2">
                                <Label>Description</Label>
                                <Textarea
                                    className="bg-muted/50 border-none rounded-2xl min-h-[100px]"
                                    value={experienceForm.description}
                                    onChange={(e) => setExperienceForm({ ...experienceForm, description: e.target.value })}
                                    placeholder="Describe your responsibilities and achievements..."
                                />
                            </div>
                        </div>
                        <DialogFooter>
                            <Button variant="outline" className="rounded-xl h-12 px-6 font-bold" onClick={() => setIsAddingExperience(false)}>Cancel</Button>
                            <Button
                                className="rounded-xl h-12 px-8 font-bold shadow-lg shadow-primary/20"
                                onClick={handleAddExperience}
                                disabled={saving}
                            >
                                {saving && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                                {editingExpId ? "Save Changes" : "Add Experience"}
                            </Button>
                        </DialogFooter>
                    </DialogContent>
                </Dialog>

                <Card className="border-none shadow-sm rounded-3xl p-8 space-y-6">
                    <div className="flex items-center justify-between">
                        <h3 className="text-xl font-bold">Skills & Expertise</h3>
                        <div className="flex gap-2">
                            <Input
                                id="new-skill"
                                placeholder="Add skill..."
                                className="h-8 w-32 bg-muted/50 border-none rounded-lg text-xs"
                                onKeyDown={(e) => {
                                    if (e.key === 'Enter') {
                                        addSkill(e.currentTarget.value)
                                        e.currentTarget.value = ""
                                    }
                                }}
                            />
                            <Button
                                variant="ghost"
                                size="sm"
                                className="text-primary hover:bg-primary/5 rounded-lg h-8 px-2"
                                onClick={() => {
                                    const input = document.getElementById('new-skill') as HTMLInputElement
                                    addSkill(input.value)
                                    input.value = ""
                                }}
                            >
                                <Plus className="h-4 w-4" />
                            </Button>
                        </div>
                    </div>
                    <div className="flex flex-wrap gap-2">
                        {formData.skills.map((skill: string) => (
                            <Badge key={skill} className="bg-primary/10 text-primary border-none hover:bg-primary hover:text-white transition-all cursor-pointer px-4 py-2 rounded-xl text-xs font-bold flex items-center gap-2 group">
                                {skill}
                                <X className="h-3 w-3 opacity-50 group-hover:opacity-100" onClick={(e) => {
                                    e.stopPropagation()
                                    removeSkill(skill)
                                }} />
                            </Badge>
                        ))}
                    </div>
                </Card>

                <div className="flex justify-end gap-3">
                    <Button variant="outline" className="rounded-xl h-12 px-8 font-bold" onClick={() => window.location.reload()}>Discard Changes</Button>
                    <Button
                        className="rounded-xl h-12 px-10 font-bold shadow-lg shadow-primary/20"
                        onClick={handleSave}
                        disabled={saving}
                    >
                        {saving && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                        Save Profile
                    </Button>
                </div>
            </div>
        </motion.div>
    )
}

"use client"

import { motion } from "framer-motion"
import {
    Card,
    CardContent,
    CardHeader,
    CardTitle,
    CardDescription
} from "@/components/ui/card"
import {
    ResponsiveContainer,
    Radar,
    RadarChart,
    PolarGrid,
    PolarAngleAxis,
    PolarRadiusAxis
} from 'recharts'
import {
    Download,
    Brain,
    Sparkles,
    Target,
    Lightbulb,
    Loader2
} from "lucide-react"
import { useEffect, useState } from "react"
import api from "@/lib/api"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"

export default function CandidateReportsPage() {
    const [report, setReport] = useState<any>(null)
    const [loading, setLoading] = useState(true)

    useEffect(() => {
        const fetchReport = async () => {
            try {
                // Get the most recent completed interview
                const response = await api.get('/interviews')
                const completed = response.data.filter((i: any) => i.status === 'completed')
                if (completed.length > 0) {
                    setReport(completed[0])
                }
            } catch (error) {
                console.error("Failed to fetch report", error)
            } finally {
                setLoading(false)
            }
        }
        fetchReport()
    }, [])

    if (loading) return (
        <div className="flex items-center justify-center p-20">
            <Loader2 className="h-8 w-8 animate-spin text-primary" />
        </div>
    )

    if (!report) return (
        <div className="text-center p-20 space-y-4">
            <Brain className="h-16 w-16 mx-auto text-muted-foreground opacity-20" />
            <h2 className="text-2xl font-bold">No reports available yet.</h2>
            <p className="text-muted-foreground">Complete an interview to see your AI analysis here.</p>
        </div>
    )

    // Map backend feedback to radarData structure
    // Map backend feedback to radarData structure
    const analysis = report.application?.feedback || report.feedback || report.report?.detailedAnalysis;
    const reportText = analysis?.text || report.report?.detailedAnalysis?.summary || "";

    // Helper to extract sections from plain text report
    const extractSection = (text: string, title: string) => {
        const regex = new RegExp(`${title}:\\s*([\\s\\S]*?)(?=\\n\\n|\\nStrengths:|\\nAreas|$)`, 'i');
        const match = text.match(regex);
        return match ? match[1].trim() : "";
    };

    const radarData = [
        { subject: 'Communication', A: (analysis?.communication_score * 10) || (analysis?.scores?.communication) || 80, fullMark: 100 },
        { subject: 'Technical skills', A: (analysis?.technical_score * 10) || (analysis?.scores?.technical) || (report.score) || 70, fullMark: 100 },
        { subject: 'Problem Solving', A: (analysis?.problem_solving_score * 10) || (analysis?.scores?.problemSolving) || 65, fullMark: 100 },
        { subject: 'Behavioral', A: (analysis?.behavioral_score * 10) || (analysis?.scores?.behavioral) || 75, fullMark: 100 },
        { subject: 'Culture Fit', A: (analysis?.culture_fit_score * 10) || (analysis?.scores?.culture) || 85, fullMark: 100 },
    ]
    return (
        <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
            className="space-y-8"
        >
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div className="flex flex-col gap-2">
                    <h1 className="text-3xl font-bold tracking-tight">Reports & Feedback</h1>
                    <p className="text-muted-foreground">Deep dive into your AI-generated interview performance analysis.</p>
                </div>
                <Button className="rounded-xl h-11 font-bold shadow-lg shadow-primary/20">
                    <Download className="mr-2 h-4 w-4" />
                    Download Full Report
                </Button>
            </div>

            <div className="grid gap-6 lg:grid-cols-5">
                {/* Left: Chart */}
                <Card className="lg:col-span-3 border-none shadow-sm rounded-3xl overflow-hidden p-6 bg-white dark:bg-card">
                    <CardHeader className="px-0 pt-0 pb-6">
                        <CardTitle className="text-xl font-bold flex items-center gap-2">
                            <Brain className="h-5 w-5 text-primary" />
                            Performance Breakdown
                        </CardTitle>
                    </CardHeader>
                    <div className="h-[400px] w-full">
                        <ResponsiveContainer width="100%" height="100%">
                            <RadarChart cx="50%" cy="50%" outerRadius="80%" data={radarData}>
                                <PolarGrid stroke="hsl(var(--muted-foreground))" strokeOpacity={0.2} />
                                <PolarAngleAxis
                                    dataKey="subject"
                                    tick={{ fill: 'hsl(var(--foreground))', fontSize: 12, fontWeight: 500 }}
                                />
                                <PolarRadiusAxis
                                    angle={30}
                                    domain={[0, 100]}
                                    tick={false}
                                    axisLine={false}
                                />
                                <Radar
                                    name="Performance"
                                    dataKey="A"
                                    stroke="hsl(var(--primary))"
                                    fill="hsl(var(--primary))"
                                    fillOpacity={0.4}
                                />
                            </RadarChart>
                        </ResponsiveContainer>
                    </div>
                </Card>

                {/* Right: AI Summary */}
                <Card className="lg:col-span-2 border-none shadow-sm rounded-3xl p-8 space-y-6 bg-primary text-primary-foreground relative overflow-hidden">
                    <div className="absolute top-0 right-0 p-8 opacity-10">
                        <Sparkles className="h-32 w-32" />
                    </div>
                    <div className="relative z-10 space-y-6">
                        <div className="space-y-2">
                            <Badge className="bg-white/20 text-white border-white/30 backdrop-blur-md px-3 font-bold">AI EXECUTIVE SUMMARY</Badge>
                            <h2 className="text-3xl font-bold pt-2">
                                {report.score > 80 ? "Exceptional potential." : "Growing consistently."}
                            </h2>
                        </div>
                        <p className="text-primary-foreground/90 leading-relaxed text-lg italic">
                            "{analysis?.summary || extractSection(reportText, 'Feedback') || analysis?.detailed_feedback || "Your AI analysis is being processed. Check back soon for deep insights into your performance."}"
                        </p>
                        <div className="grid grid-cols-2 gap-4 pt-4 border-t border-white/10">
                            <div>
                                <p className="text-[10px] uppercase tracking-widest font-bold text-white/60 mb-1">Overall Rating</p>
                                <p className="text-2xl font-bold font-mono">{report.score}/100</p>
                            </div>
                            <div>
                                <p className="text-[10px] uppercase tracking-widest font-bold text-white/60 mb-1">Fit for Role</p>
                                <p className="text-2xl font-bold font-mono">{report.fitDecision || "PENDING"}</p>
                            </div>
                        </div>
                    </div>
                </Card>
            </div>

            <div className="grid gap-6 md:grid-cols-2">
                <Card className="border-none shadow-sm rounded-3xl p-8 space-y-6">
                    <h3 className="text-xl font-bold flex items-center gap-2">
                        <Target className="h-5 w-5 text-green-500" />
                        Key Strengths
                    </h3>
                    <ul className="space-y-4">
                        {(Array.isArray(analysis?.strengths) ? analysis.strengths :
                            extractSection(reportText, 'Strengths').split('\n-').map(s => s.replace(/^- /, '').trim()).filter(Boolean) || [
                                "Articulate communication of design rationale.",
                                "Strong grasp of technical constraints and feasibility.",
                            ]).map((strength: string, i: number) => (
                                <li key={i} className="flex gap-3 text-sm font-medium p-4 rounded-2xl bg-green-500/5 text-green-700 dark:text-green-400">
                                    <span className="flex-shrink-0 h-5 w-5 bg-green-500 text-white rounded-full flex items-center justify-center text-[10px] font-bold">✓</span>
                                    {strength}
                                </li>
                            ))}
                    </ul>
                </Card>

                <Card className="border-none shadow-sm rounded-3xl p-8 space-y-6">
                    <h3 className="text-xl font-bold flex items-center gap-2">
                        <Lightbulb className="h-5 w-5 text-amber-500" />
                        Areas for Improvement
                    </h3>
                    <ul className="space-y-4">
                        {(Array.isArray(analysis?.weaknesses) ? analysis.weaknesses :
                            extractSection(reportText, 'Areas for Improvement').split('\n-').map(s => s.replace(/^- /, '').trim()).filter(Boolean) || [
                                "Further deep dive into data-driven design metrics.",
                                "Exploring more divergent ideation during whiteboarding.",
                            ]).map((growth: string, i: number) => (
                                <li key={i} className="flex gap-3 text-sm font-medium p-4 rounded-2xl bg-amber-500/5 text-amber-700 dark:text-amber-400">
                                    <span className="flex-shrink-0 h-5 w-5 bg-amber-500 text-white rounded-full flex items-center justify-center text-[10px] font-bold">!</span>
                                    {growth}
                                </li>
                            ))}
                    </ul>
                </Card>
            </div>
        </motion.div>
    )

}

"use client"

import { useState, useEffect } from "react"
import {
    Calendar,
    ChevronDown,
    Filter,
    MoreHorizontal,
    Plus,
    Search,
    User,
} from "lucide-react"

import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
    Card,
    CardContent,
    CardDescription,
    CardHeader,
    CardTitle,
} from "@/components/ui/card"
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuLabel,
    DropdownMenuSeparator,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Input } from "@/components/ui/input"
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select"
import { Separator } from "@/components/ui/separator"
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table"
import api from "@/lib/api"
import Link from "next/link"

interface Candidate {
    id: string;
    userId: string;
    skills: string[];
    experience: number;
    education: string[];
    location: string;
    user: {
        firstName: string;
        lastName: string;
        email: string;
    };
    createdAt: string;
}

import { AddCandidateDialog } from "@/components/candidates/AddCandidateDialog"
import { useRouter } from "next/navigation"

export default function CandidatesPage() {
    const [candidates, setCandidates] = useState<Candidate[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState("");
    const router = useRouter();

    useEffect(() => {
        fetchCandidates();
    }, []);

    const fetchCandidates = async () => {
        try {
            const response = await api.get('/candidates');
            setCandidates(response.data);
        } catch (error) {
            console.error("Failed to fetch candidates", error);
        } finally {
            setLoading(false);
        }
    };

    const handleStartInterview = async (candidateId: string) => {
        try {
            // In a real app, we'd select a job. For MVP, we'll try to find an existing job or use a placeholder.
            const jobsResponse = await api.get('/jobs');
            const job = jobsResponse.data[0]; // Use the first available job

            if (!job) {
                alert("Please create a job first before starting an interview.");
                return;
            }

            const response = await api.post('/interviews', {
                candidateId: candidateId,
                jobId: job.id,
                status: 'Scheduled'
            });

            alert("Interview started!");
            router.push(`/interview/room/${response.data.id}`);
        } catch (error) {
            console.error("Failed to start interview", error);
            alert("Failed to start interview.");
        }
    };

    const filteredCandidates = candidates.filter(c => {
        const fullName = `${c.user?.firstName} ${c.user?.lastName}`.toLowerCase();
        return fullName.includes(searchQuery.toLowerCase()) ||
            c.user?.email?.toLowerCase().includes(searchQuery.toLowerCase()) ||
            (c.skills && c.skills.some(s => s.toLowerCase().includes(searchQuery.toLowerCase())));
    });

    const formatDate = (dateString: string) => {
        return new Date(dateString).toLocaleDateString();
    }

    return (
        <div className="flex flex-col gap-4 p-4 md:p-8">
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-3xl font-bold tracking-tight">Candidates</h2>
                    <p className="text-muted-foreground">
                        Manage your candidate database and initiate AI interviews.
                    </p>
                </div>
                <AddCandidateDialog onCandidateAdded={fetchCandidates} />
            </div>

            <Separator />

            <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
                <div className="flex items-center gap-2">
                    <div className="relative">
                        <Search className="text-muted-foreground absolute left-2.5 top-2.5 h-4 w-4" />
                        <Input
                            placeholder="Search candidates by name, email, or skill..."
                            className="pl-8 w-[250px] md:w-[400px]"
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                        />
                    </div>
                </div>
                <div className="text-muted-foreground text-sm">
                    Showing <strong>{filteredCandidates.length}</strong> candidates
                </div>
            </div>

            <Card>
                <CardHeader>
                    <CardTitle>All Candidates</CardTitle>
                    <CardDescription>
                        A list of all candidates in your system.
                    </CardDescription>
                </CardHeader>
                <CardContent>
                    <Table>
                        <TableHeader>
                            <TableRow>
                                <TableHead>Candidate</TableHead>
                                <TableHead>Location</TableHead>
                                <TableHead>Experience</TableHead>
                                <TableHead>Skills</TableHead>
                                <TableHead>Added Date</TableHead>
                                <TableHead className="text-right">Actions</TableHead>
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {loading ? (
                                <TableRow>
                                    <TableCell colSpan={6} className="text-center py-10">Loading candidates...</TableCell>
                                </TableRow>
                            ) : filteredCandidates.length === 0 ? (
                                <TableRow>
                                    <TableCell colSpan={6} className="text-center py-10">No candidates found.</TableCell>
                                </TableRow>
                            ) : (
                                filteredCandidates.map((candidate) => {
                                    const name = candidate.user ? `${candidate.user.firstName} ${candidate.user.lastName}` : 'Unknown';
                                    const initials = name.split(" ").map(n => n[0]).join("");

                                    return (
                                        <TableRow key={candidate.id}>
                                            <TableCell>
                                                <Link href={`/candidates/${candidate.id}`} className="flex items-center gap-3 group">
                                                    <Avatar className="group-hover:ring-2 group-hover:ring-primary transition-all">
                                                        <AvatarFallback>{initials}</AvatarFallback>
                                                    </Avatar>
                                                    <div>
                                                        <div className="font-medium group-hover:text-primary transition-colors">
                                                            {name}
                                                        </div>
                                                        <div className="text-xs text-muted-foreground">{candidate.user?.email}</div>
                                                    </div>
                                                </Link>
                                            </TableCell>
                                            <TableCell>{candidate.location}</TableCell>
                                            <TableCell>{candidate.experience} years</TableCell>
                                            <TableCell>
                                                <div className="flex flex-wrap gap-1 max-w-[200px]">
                                                    {candidate.skills?.slice(0, 3).map(skill => (
                                                        <Badge key={skill} variant="outline" className="text-[10px] px-1 py-0">{skill}</Badge>
                                                    ))}
                                                    {(candidate.skills?.length || 0) > 3 && <span className="text-[10px] text-muted-foreground">+{(candidate.skills?.length || 0) - 3} more</span>}
                                                </div>
                                            </TableCell>
                                            <TableCell>{formatDate(candidate.createdAt)}</TableCell>
                                            <TableCell className="text-right">
                                                <DropdownMenu>
                                                    <DropdownMenuTrigger asChild>
                                                        <Button variant="ghost" className="h-8 w-8 p-0">
                                                            <span className="sr-only">Open menu</span>
                                                            <MoreHorizontal className="h-4 w-4" />
                                                        </Button>
                                                    </DropdownMenuTrigger>
                                                    <DropdownMenuContent align="end">
                                                        <DropdownMenuItem onClick={() => handleStartInterview(candidate.id)}>
                                                            Start AI Interview
                                                        </DropdownMenuItem>
                                                        <DropdownMenuSeparator />
                                                        <DropdownMenuItem className="text-destructive">
                                                            Delete Profile
                                                        </DropdownMenuItem>
                                                    </DropdownMenuContent>
                                                </DropdownMenu>
                                            </TableCell>
                                        </TableRow>
                                    );
                                })
                            )}
                        </TableBody>
                    </Table>
                </CardContent>
            </Card>
        </div>
    )
}

"use client";

import { useState, useEffect, useRef } from "react";
import { useParams, useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Mic, Loader2 } from "lucide-react";
import api from "@/lib/api";
import DIdAvatar from "@/components/interview/DIdAvatar";
import { WebcamPreview } from "@/components/interview/WebcamPreview";
import { useWebSpeech } from "@/hooks/useWebSpeech";
import { avatarStateManager } from "@/lib/InterviewAvatarStateManager";

export default function InterviewRoomPage() {
    const params = useParams();
    const router = useRouter();
    const interviewId = params.id as string;

    useEffect(() => {
        const performRedirect = async () => {
            const token = localStorage.getItem('token');
            if (interviewId && token) {
                try {
                    const response = await api.get(`/interviews/${interviewId}`);
                    const candidateInterview = response.data;
                    const appId = candidateInterview.applicationId;

                    // Construct URL explicitly with trailing slash to avoid Express redirects
                    const streamUrl = process.env.NEXT_PUBLIC_DID_STREAMING_URL || 'http://localhost:3001';
                    const finalUrl = `${streamUrl}?applicationId=${encodeURIComponent(appId || '')}&interviewId=${encodeURIComponent(interviewId)}&token=${encodeURIComponent(token)}`;

                    console.log("NAVIGATING TO INTERVIEW ROOM (PORT 3001):", finalUrl);
                    window.location.href = finalUrl;
                } catch (err) {
                    console.error("Failed to fetch interview details for redirect", err);
                    const streamUrl = process.env.NEXT_PUBLIC_DID_STREAMING_URL || 'http://localhost:3001';
                    const finalUrl = `${streamUrl}?interviewId=${encodeURIComponent(interviewId)}&token=${encodeURIComponent(token)}`;
                    console.log("FALLBACK NAVIGATING TO INTERVIEW ROOM:", finalUrl);
                    window.location.href = finalUrl;
                }
            }
        };

        performRedirect();
    }, [interviewId]);

    const [interview, setInterview] = useState<any>(null);
    const [currentQuestion, setCurrentQuestion] = useState<any>(null);
    const [loading, setLoading] = useState(true);
    const [processing, setProcessing] = useState(false);
    const [messages, setMessages] = useState<any[]>([]);
    const [answerText, setAnswerText] = useState("");
    const [hasStarted, setHasStarted] = useState(false);
    const [isSpeaking, setIsSpeaking] = useState(false);

    const { transcript, interimTranscript, isListening, startListening, stopListening, resetTranscript } = useWebSpeech();

    const silenceTimerRef = useRef<NodeJS.Timeout | null>(null);
    const messagesEndRef = useRef<HTMLDivElement>(null);

    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    };

    useEffect(() => {
        scrollToBottom();
    }, [messages, answerText, interimTranscript]);

    useEffect(() => {
        if (transcript) {
            setAnswerText(transcript);
        }
    }, [transcript]);

    // HANDS-FREE AUTOMATION: Control microphone based on AI status
    useEffect(() => {
        if (hasStarted && !isSpeaking && !processing && !isListening) {
            startListening();
        } else if ((isSpeaking || processing) && isListening) {
            stopListening();
        }
    }, [isSpeaking, processing, hasStarted, isListening]);

    // HANDS-FREE AUTOMATION: Silence detection (4s of inactivity triggers submission)
    useEffect(() => {
        if (silenceTimerRef.current) clearTimeout(silenceTimerRef.current);

        if (isListening && (transcript || interimTranscript) && !processing) {
            silenceTimerRef.current = setTimeout(() => {
                const finalAnswer = (transcript || answerText || interimTranscript).trim();
                if (finalAnswer.length > 5) {
                    handleAnswerSubmit(finalAnswer);
                }
            }, 4000);
        }

        return () => { if (silenceTimerRef.current) clearTimeout(silenceTimerRef.current); };
    }, [transcript, interimTranscript, isListening, processing, answerText]);

    useEffect(() => {
        const initSession = async () => {
            try {
                const response = await api.post(`/interviews/${interviewId}/start`);
                const data = response.data;
                if (data.status === 'completed') {
                    router.push(`/candidates/interviews/${interviewId}/report`);
                    return;
                }
                if (data.question) {
                    setCurrentQuestion(data.question);
                    setMessages(prev => {
                        if (prev.find(m => m.id === data.question.id)) return prev;
                        return [...prev, { role: 'ai', content: data.question.questionText, id: data.question.id }];
                    });
                }
                const details = await api.get(`/interviews/${interviewId}`);
                setInterview(details.data);
            } catch (error) {
                console.error("Failed to start session", error);
            } finally {
                setLoading(false);
            }
        };

        if (interviewId) {
            initSession();
        }

        return () => {
            stopListening();
            if (silenceTimerRef.current) clearTimeout(silenceTimerRef.current);
        };
    }, [interviewId]);

    const startInterview = async () => {
        setHasStarted(true);
        setProcessing(true);
        try {
            const response = await api.post(`/interviews/${interviewId}/start`);
            const data = response.data;
            if (data.question) {
                setCurrentQuestion(data.question);
                setMessages([{ role: 'ai', content: data.question.questionText, id: data.question.id }]);
            }
        } catch (err) {
            console.error("Start interview failed", err);
        } finally {
            setProcessing(false);
        }
    };

    const handleAnswerSubmit = async (textToSubmit?: string) => {
        const finalContent = textToSubmit || answerText;
        if (!finalContent.trim() || processing) return;

        setProcessing(true);
        stopListening();
        resetTranscript();
        setAnswerText("");

        const userMsg = { role: 'user', content: finalContent };
        setMessages(prev => [...prev, userMsg]);

        try {
            avatarStateManager.setTHINKING();
            const response = await api.post(`/interviews/${interviewId}/answer`, { answer: userMsg.content });
            const data = response.data;

            if (data.status === 'completed') {
                router.push(`/candidates/interviews/${interviewId}/report`);
                return;
            }

            if (data.question) {
                setCurrentQuestion(data.question);
                setMessages(prev => [...prev, { role: 'ai', content: data.question.questionText, id: data.question.id }]);
            }

        } catch (error) {
            console.error("Failed to submit answer", error);
            avatarStateManager.setIDLE();
        } finally {
            setProcessing(false);
        }
    };

    if (loading) {
        return <div className="flex h-screen items-center justify-center bg-slate-950"><Loader2 className="animate-spin h-8 w-8 text-blue-500" /></div>;
    }

    return (
        <div className="flex h-screen bg-[#020617] overflow-hidden relative font-sans text-slate-200">
            {!hasStarted && (
                <div className="absolute inset-0 z-50 bg-[#020617] flex flex-col items-center justify-center text-white p-4">
                    <div className="w-24 h-24 bg-blue-600 rounded-full flex items-center justify-center mb-8 animate-pulse shadow-[0_0_50px_rgba(37,99,235,0.4)]">
                        <Mic className="h-10 w-10 text-white" />
                    </div>
                    <h1 className="text-4xl font-bold mb-4 tracking-tight">Technical Interview Session</h1>
                    <p className="text-slate-400 mb-12 max-w-sm text-center leading-relaxed text-lg">
                        Meet your AI interviewer. The session is voice-controlled for a natural experience.
                    </p>
                    <Button onClick={startInterview} size="lg" className="bg-blue-600 hover:bg-blue-700 text-xl px-16 py-10 rounded-full shadow-2xl transition-all hover:scale-105 active:scale-95 border-b-4 border-blue-800">
                        Join Interview Room
                    </Button>
                </div>
            )}

            {/* Stage Area (Avatar) */}
            <div className="flex-1 relative flex flex-col items-center justify-center p-12 bg-gradient-to-b from-[#020617] to-[#0f172a] overflow-hidden border-r border-white/5">
                {/* Header Overlay */}
                <div className="absolute top-8 left-12 right-12 flex justify-between items-start z-10">
                    <div className="flex flex-col gap-1">
                        <div className="flex items-center gap-3 bg-white/5 backdrop-blur-md border border-white/10 px-4 py-2 rounded-2xl">
                            <div className="w-2.5 h-2.5 bg-blue-500 rounded-full animate-pulse shadow-[0_0_10px_rgba(59,130,246,0.5)]" />
                            <span className="text-xs font-bold tracking-wider uppercase text-blue-100/80">Alex • Senior Interviewer</span>
                        </div>
                    </div>
                </div>

                {/* Avatar Frame */}
                <div className="relative h-full aspect-video rounded-3xl overflow-hidden shadow-[0_0_150px_rgba(0,0,0,0.8),0_0_50px_rgba(30,41,59,0.3)] border border-white/10 bg-black group flex items-center justify-center">
                    <DIdAvatar
                        interviewId={interviewId}
                        onStatusChange={(speaking) => setIsSpeaking(speaking)}
                        onStop={() => setIsSpeaking(false)}
                    />

                    {/* Status Overlays */}
                    <div className="absolute bottom-6 left-6 flex items-center gap-3 z-20">
                        <div className={`px-4 py-2 rounded-xl flex items-center gap-3 transition-all duration-700 backdrop-blur-xl border ${isListening ? 'bg-red-500/20 border-red-500/40 text-red-100' : 'bg-white/5 border-white/10 text-slate-400'}`}>
                            <div className={`h-2 w-2 rounded-full ${isListening ? 'bg-red-500 animate-ping' : 'bg-slate-600'}`} />
                            <span className="text-[10px] font-bold uppercase tracking-[0.2em]">
                                {processing ? 'Analyzing' : isListening ? 'Listening' : 'Ready'}
                            </span>
                        </div>
                    </div>

                    {/* Self Preview */}
                    <div className="absolute bottom-6 right-6 w-44 aspect-video shadow-2xl rounded-2xl overflow-hidden border border-white/10 ring-1 ring-white/20 transition-transform hover:scale-105 duration-300">
                        <WebcamPreview />
                    </div>
                </div>

                {/* Progress Bar (at the bottom of the stage) */}
                <div className="absolute bottom-12 left-24 right-24 h-1.5 bg-white/5 rounded-full overflow-hidden">
                    {isListening && !processing && (
                        <div className="h-full bg-blue-500 animate-progress w-full shadow-[0_0_15px_rgba(59,130,246,0.5)]" style={{ animationDuration: '4s' }} />
                    )}
                </div>
            </div>

            {/* Sidebar (Transcript) */}
            <div className="w-[400px] flex flex-col h-full bg-[#020617] border-l border-white/5">
                <div className="p-8 border-b border-white/5 flex flex-col gap-4">
                    <div className="flex justify-between items-center">
                        <div className="flex items-center gap-3">
                            <div className="h-8 w-8 bg-blue-600/20 rounded-lg flex items-center justify-center">
                                <Mic className="h-4 w-4 text-blue-500" />
                            </div>
                            <h2 className="text-sm font-bold text-white tracking-tight leading-none">Conduction Log</h2>
                        </div>
                        <Badge className="bg-white/5 border-white/10 text-white text-[10px] tracking-widest uppercase">Question {currentQuestion?.orderNumber || 1}</Badge>
                    </div>
                </div>

                <ScrollArea className="flex-1 px-6 py-8">
                    <div className="space-y-8 pb-20">
                        {messages.map((msg, idx) => (
                            <div key={idx} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'} animate-in fade-in slide-in-from-bottom-4 duration-500`}>
                                <div className={`flex items-center gap-2 mb-2 text-[9px] font-bold uppercase tracking-widest ${msg.role === 'user' ? 'text-blue-500' : 'text-slate-500'}`}>
                                    {msg.role === 'user' ? 'Candidate' : 'Alex'}
                                </div>
                                <div className={`max-w-[90%] rounded-2xl p-4 text-sm font-medium leading-relaxed transition-all ${msg.role === 'user'
                                    ? 'bg-blue-600 text-white rounded-tr-none shadow-lg shadow-blue-900/20'
                                    : 'bg-white/5 border border-white/10 text-slate-300 rounded-tl-none'
                                    }`}>
                                    <p className="whitespace-pre-wrap">{msg.content}</p>
                                </div>
                            </div>
                        ))}

                        {(isListening || processing) && (
                            <div className="flex flex-col items-end animate-in fade-in slide-in-from-bottom-2 duration-300">
                                <div className={`max-w-[90%] w-full rounded-2xl p-4 border transition-all duration-500 rounded-tr-none ${processing ? 'bg-white/5 border-white/10 text-slate-500' :
                                    'bg-blue-600/10 border-blue-500/30 text-blue-100'}`}>
                                    <p className="text-sm italic leading-relaxed">
                                        {answerText || (interimTranscript ? `${interimTranscript}...` : "...")}
                                    </p>
                                    <div className="mt-3 flex items-center gap-2">
                                        <div className="flex gap-1">
                                            <div className="w-1 h-1 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
                                            <div className="w-1 h-1 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '150ms' }} />
                                            <div className="w-1 h-1 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '300ms' }} />
                                        </div>
                                        <span className="text-[9px] font-bold uppercase tracking-widest text-blue-500/70">
                                            {processing ? 'Analyzing response' : 'Listening...'}
                                        </span>
                                    </div>
                                </div>
                            </div>
                        )}
                        <div ref={messagesEndRef} />
                    </div>
                </ScrollArea>
            </div>
        </div>
    );
}

"use client"

import { useState, useEffect } from "react"
import {
    Briefcase,
    Calendar,
    Filter,
    MapPin,
    MoreHorizontal,
    Plus,
    Search,
    Users,
} from "lucide-react"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
    Card,
    CardContent,
    CardDescription,
    CardFooter,
    CardHeader,
    CardTitle,
} from "@/components/ui/card"
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuLabel,
    DropdownMenuSeparator,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Input } from "@/components/ui/input"
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select"
import { Separator } from "@/components/ui/separator"
import api from "@/lib/api"
import Link from "next/link"
import { JobDetailsDialog } from "@/components/jobs/JobDetailsDialog"

interface Job {
    id: string;
    title: string;
    department: string;
    location: string;
    type: string;
    status: string;
    createdAt: string;
    applicantCount?: number;
}

import { CreateJobDialog } from "@/components/jobs/CreateJobDialog"

export default function JobsPage() {
    const [jobs, setJobs] = useState<Job[]>([])
    const [loading, setLoading] = useState(true)
    const [filterStatus, setFilterStatus] = useState("all")

    useEffect(() => {
        fetchJobs();
    }, []);

    const fetchJobs = async () => {
        try {
            const response = await api.get('/jobs');
            setJobs(response.data);
        } catch (error) {
            console.error("Failed to fetch jobs", error);
        } finally {
            setLoading(false);
        }
    };

    const handleJobCreated = () => {
        fetchJobs();
    };

    const handleDeleteJob = async (jobId: string) => {
        if (!confirm("Are you sure you want to delete this job? This will also remove all candidate applications for this role.")) return;

        try {
            await api.delete(`/jobs/${jobId}`);
            setJobs(prev => prev.filter(j => j.id !== jobId));
        } catch (error) {
            console.error("Failed to delete job", error);
            alert("Failed to delete job. Please try again.");
        }
    };

    const filteredJobs =
        filterStatus === "all"
            ? jobs
            : jobs.filter((job) => job.status.toLowerCase() === filterStatus)

    const formatDate = (dateString: string) => {
        const date = new Date(dateString);
        return new Intl.RelativeTimeFormat('en', { numeric: 'auto' }).format(
            Math.ceil((date.getTime() - Date.now()) / (1000 * 60 * 60 * 24)),
            'day'
        );
    }

    if (loading) return <div className="p-8">Loading jobs...</div>

    return (
        <div className="flex flex-col gap-4 p-4 md:p-8">
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-3xl font-bold tracking-tight">Jobs</h2>
                    <p className="text-muted-foreground">
                        Manage your open positions and track candidates.
                    </p>
                </div>
                <CreateJobDialog onJobCreated={handleJobCreated} />
            </div>

            <Separator />

            <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
                <div className="flex items-center gap-2">
                    <div className="relative">
                        <Search className="text-muted-foreground absolute left-2.5 top-2.5 h-4 w-4" />
                        <Input
                            placeholder="Search jobs..."
                            className="pl-8 w-[250px] md:w-[300px]"
                        />
                    </div>
                    <Select value={filterStatus} onValueChange={setFilterStatus}>
                        <SelectTrigger className="w-[180px]">
                            <div className="flex items-center gap-2">
                                <Filter className="h-4 w-4" />
                                <SelectValue placeholder="Status" />
                            </div>
                        </SelectTrigger>
                        <SelectContent>
                            <SelectItem value="all">All Statuses</SelectItem>
                            <SelectItem value="active">Active</SelectItem>
                            <SelectItem value="draft">Draft</SelectItem>
                            <SelectItem value="closed">Closed</SelectItem>
                        </SelectContent>
                    </Select>
                </div>
                <div className="text-muted-foreground text-sm">
                    Showing <strong>{filteredJobs.length}</strong> jobs
                </div>
            </div>

            <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
                {filteredJobs.map((job) => (
                    <Card key={job.id} className="transition-all hover:shadow-md border-none shadow-sm rounded-3xl overflow-hidden flex flex-col">
                        <CardHeader className="pb-4">
                            <div className="flex items-start justify-between">
                                <div className="space-y-1">
                                    <JobDetailsDialog
                                        job={job as any}
                                        userRole="recruiter"
                                        trigger={
                                            <CardTitle className="text-xl font-bold cursor-pointer hover:text-primary transition-colors">
                                                {job.title}
                                            </CardTitle>
                                        }
                                    />
                                    <CardDescription className="flex items-center gap-1 font-semibold text-primary">
                                        <Briefcase className="h-3 w-3" /> {job.department || ''}
                                    </CardDescription>
                                </div>
                                <DropdownMenu>
                                    <DropdownMenuTrigger asChild>
                                        <Button variant="ghost" className="h-8 w-8 p-0 rounded-full">
                                            <span className="sr-only">Open menu</span>
                                            <MoreHorizontal className="h-4 w-4" />
                                        </Button>
                                    </DropdownMenuTrigger>
                                    <DropdownMenuContent align="end" className="rounded-2xl border-none shadow-xl">
                                        <DropdownMenuLabel>Actions</DropdownMenuLabel>
                                        <DropdownMenuItem className="rounded-xl">Edit Job</DropdownMenuItem>
                                        <DropdownMenuItem className="rounded-xl">View Candidates</DropdownMenuItem>
                                        <DropdownMenuSeparator />
                                        <DropdownMenuItem
                                            className="text-destructive rounded-xl"
                                            onClick={() => handleDeleteJob(job.id)}
                                        >
                                            Delete Job
                                        </DropdownMenuItem>
                                    </DropdownMenuContent>
                                </DropdownMenu>
                            </div>
                        </CardHeader>
                        <CardContent className="flex-1">
                            <div className="flex flex-col gap-2">
                                <div className="flex items-center justify-between text-sm">
                                    <div className="text-muted-foreground flex items-center gap-1 font-medium">
                                        <MapPin className="h-3 w-3" /> {job.location}
                                    </div>
                                    <Badge variant="outline" className="rounded-full bg-muted/30 border-none px-2 py-0.5 font-bold text-[10px] uppercase">
                                        {job.type}
                                    </Badge>
                                </div>
                                <div className="flex items-center justify-between mt-2">
                                    <Badge
                                        className="rounded-full px-2 py-0.5 font-bold text-[10px] uppercase"
                                        variant={
                                            job.status === "PUBLISHED" || job.status === "Active"
                                                ? "default"
                                                : job.status === "DRAFT"
                                                    ? "secondary"
                                                    : "destructive"
                                        }
                                    >
                                        {job.status}
                                    </Badge>
                                    <div className="text-muted-foreground text-[10px] font-bold uppercase flex items-center gap-1">
                                        <Calendar className="h-3 w-3" /> {formatDate(job.createdAt)}
                                    </div>
                                </div>
                            </div>
                        </CardContent>
                        <CardFooter className="bg-muted/10 flex items-center justify-between px-6 py-3 border-t border-muted/50">
                            <div className="text-muted-foreground text-xs font-bold uppercase flex items-center gap-1.5 text-primary">
                                <Users className="h-4 w-4" /> {job.applicantCount || 0} Candidates
                            </div>
                            <JobDetailsDialog
                                job={job as any}
                                userRole="recruiter"
                                trigger={
                                    <Button variant="ghost" size="sm" className="font-bold text-xs rounded-xl hover:bg-primary/5">
                                        View Details
                                    </Button>
                                }
                            />
                        </CardFooter>
                    </Card>
                ))}
            </div>
        </div>
    )
}

"use client"

import { SignIn } from "@clerk/nextjs";
import { useSearchParams, useRouter } from "next/navigation";
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Alert, AlertDescription } from "@/components/ui/alert";
import api from "@/lib/api";

export default function LoginPage() {
    const searchParams = useSearchParams();
    const router = useRouter();
    const role = searchParams.get('role');
    const redirectUrl = role ? `/onboarding?role=${role}` : "/onboarding";

    const [showLegacy, setShowLegacy] = useState(false);
    const [email, setEmail] = useState("");
    const [password, setPassword] = useState("");
    const [error, setError] = useState("");
    const [loading, setLoading] = useState(false);

    const handleLegacyLogin = async (e: React.FormEvent) => {
        e.preventDefault();
        setError("");
        setLoading(true);

        try {
            const response = await api.post('/auth/login', { email, password });
            const { access_token, user } = response.data;

            localStorage.setItem('token', access_token);
            localStorage.setItem('user', JSON.stringify(user));

            router.push(user.role === 'recruiter' ? '/recruiter' : '/candidate');
            router.refresh();
        } catch (err: any) {
            setError(err.response?.data?.message || "Invalid credentials");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="flex items-center justify-center min-h-screen bg-muted/30 px-4">
            <div className="w-full max-w-md space-y-4">
                <div className="text-center space-y-2 mb-6">
                    <h1 className="text-3xl font-bold tracking-tight text-primary">HireMe</h1>
                    <p className="text-muted-foreground text-sm font-medium">Your gateway to the next career move</p>
                </div>

                {!showLegacy ? (
                    <div className="space-y-4 animate-in fade-in slide-in-from-bottom-4 duration-500">
                        <SignIn
                            routing="path"
                            path="/login"
                            forceRedirectUrl={redirectUrl}
                            signUpForceRedirectUrl={redirectUrl}
                            appearance={{
                                elements: {
                                    rootBox: 'mx-auto w-full',
                                    card: 'shadow-xl border-border shadow-primary/5 rounded-2xl w-full',
                                    formButtonPrimary: 'bg-primary hover:bg-primary/90 text-sm font-medium h-10',
                                    footerActionLink: 'text-primary hover:text-primary/80',
                                    identityPreviewText: 'text-foreground',
                                    socialButtonsBlockButton: 'border-border hover:bg-muted/50 transition-colors',
                                    dividerLine: 'bg-border',
                                    dividerText: 'text-muted-foreground'
                                },
                            }}
                        />
                        <div className="text-center pt-2">
                            <Button
                                variant="link"
                                size="sm"
                                onClick={() => setShowLegacy(true)}
                                className="text-muted-foreground hover:text-primary"
                            >
                                Prefer legacy email/password login?
                            </Button>
                        </div>
                    </div>
                ) : (
                    <Card className="shadow-xl border-border shadow-primary/5 rounded-2xl animate-in fade-in slide-in-from-bottom-4 duration-500">
                        <CardHeader className="space-y-1">
                            <CardTitle className="text-2xl font-bold">Legacy Login</CardTitle>
                            <CardDescription>
                                Enter your email and password from your existing account
                            </CardDescription>
                        </CardHeader>
                        <CardContent className="space-y-4">
                            {error && (
                                <Alert variant="destructive" className="py-2.5">
                                    <AlertDescription className="text-xs">{error}</AlertDescription>
                                </Alert>
                            )}
                            <form onSubmit={handleLegacyLogin} className="space-y-4">
                                <div className="space-y-2">
                                    <Input
                                        type="email"
                                        placeholder="name@example.com"
                                        value={email}
                                        onChange={(e) => setEmail(e.target.value)}
                                        required
                                        className="h-10 px-4 focus-visible:ring-primary"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <Input
                                        type="password"
                                        placeholder="••••••••"
                                        value={password}
                                        onChange={(e) => setPassword(e.target.value)}
                                        required
                                        className="h-10 px-4 focus-visible:ring-primary"
                                    />
                                </div>
                                <Button
                                    type="submit"
                                    className="w-full h-10 font-medium"
                                    disabled={loading}
                                >
                                    {loading ? "Logging in..." : "Log In"}
                                </Button>
                            </form>
                            <div className="text-center pt-2">
                                <Button
                                    variant="link"
                                    size="sm"
                                    onClick={() => setShowLegacy(false)}
                                    className="text-muted-foreground hover:text-primary"
                                >
                                    Back to modern login
                                </Button>
                            </div>
                        </CardContent>
                    </Card>
                )}
            </div>
        </div>
    );
}

"use client"

import { useUser } from "@clerk/nextjs"
import { useRouter, useSearchParams } from "next/navigation"
import { useEffect, useState } from "react"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card"
import { Briefcase, Users, Loader2 } from "lucide-react"
import { motion } from "framer-motion"

export default function OnboardingPage() {
    const { user, isLoaded } = useUser()
    const router = useRouter()
    const searchParams = useSearchParams()
    const [loading, setLoading] = useState(false)

    useEffect(() => {
        if (!isLoaded || !user) return

        if (user?.unsafeMetadata?.role) {
            router.push("/")
            return
        }

        const role = searchParams.get('role') as 'candidate' | 'recruiter'
        if (role && (role === 'candidate' || role === 'recruiter')) {
            selectRole(role)
        }
    }, [isLoaded, user, searchParams, router])

    const selectRole = async (role: 'candidate' | 'recruiter') => {
        if (!user) return
        setLoading(true)
        try {
            await user.update({
                unsafeMetadata: {
                    ...user.unsafeMetadata,
                    role: role
                }
            })
            router.push("/")
        } catch (error) {
            console.error("Failed to update role", error)
        } finally {
            setLoading(false)
        }
    }

    if (!isLoaded || loading) {
        return (
            <div className="flex items-center justify-center min-h-screen">
                <Loader2 className="h-8 w-8 animate-spin text-primary" />
            </div>
        )
    }

    return (
        <div className="min-h-screen flex items-center justify-center p-4 bg-muted/30">
            <div className="max-w-2xl w-full space-y-8">
                <div className="text-center space-y-2">
                    <h1 className="text-3xl font-bold tracking-tight">Welcome to HireMe</h1>
                    <p className="text-muted-foreground italic">One last step to get you started</p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {/* Recruiter Card */}
                    <motion.div
                        whileHover={{ y: -5 }}
                        whileTap={{ scale: 0.98 }}
                    >
                        <Card
                            className="cursor-pointer border-2 hover:border-primary transition-colors h-full"
                            onClick={() => selectRole('recruiter')}
                        >
                            <CardHeader className="text-center">
                                <div className="mx-auto bg-primary/10 p-4 rounded-full w-16 h-16 flex items-center justify-center mb-4">
                                    <Briefcase className="h-8 w-8 text-primary" />
                                </div>
                                <CardTitle>I'm a Recruiter</CardTitle>
                                <CardDescription>I want to hire top talent and automate my interview process.</CardDescription>
                            </CardHeader>
                        </Card>
                    </motion.div>

                    {/* Candidate Card */}
                    <motion.div
                        whileHover={{ y: -5 }}
                        whileTap={{ scale: 0.98 }}
                    >
                        <Card
                            className="cursor-pointer border-2 hover:border-primary transition-colors h-full"
                            onClick={() => selectRole('candidate')}
                        >
                            <CardHeader className="text-center">
                                <div className="mx-auto bg-primary/10 p-4 rounded-full w-16 h-16 flex items-center justify-center mb-4">
                                    <Users className="h-8 w-8 text-primary" />
                                </div>
                                <CardTitle>I'm a Candidate</CardTitle>
                                <CardDescription>I want to find my dream job and showcase my skills.</CardDescription>
                            </CardHeader>
                        </Card>
                    </motion.div>
                </div>

                <div className="text-center">
                    <p className="text-xs text-muted-foreground">
                        By selecting a role, you agree to our Terms of Service and Privacy Policy.
                    </p>
                </div>
            </div>
        </div>
    )
}

"use client"

import { useState, useEffect, useRef } from "react"
import { useParams, useRouter } from "next/navigation"
import { motion } from "framer-motion"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
    Video,
    MessageSquare,
    Loader2,
    X,
    User,
    ShieldAlert,
    Clock,
    Signal,
    Power
} from "lucide-react"
import api from "@/lib/api"
import { getFreshToken } from "@/lib/tokenManager"
import { io, Socket } from "socket.io-client"
import { toast } from "sonner"

export default function RecruiterMonitorPage() {
    const params = useParams()
    const router = useRouter()
    const interviewId = params.id as string

    const [interview, setInterview] = useState<any>(null)
    const [messages, setMessages] = useState<any[]>([])
    const [loading, setLoading] = useState(true)
    const [socket, setSocket] = useState<Socket | null>(null)
    const [peerConnection, setPeerConnection] = useState<RTCPeerConnection | null>(null)
    const [remoteStream, setRemoteStream] = useState<MediaStream | null>(null)
    const [isTerminating, setIsTerminating] = useState(false)

    const videoRef = useRef<HTMLVideoElement>(null)
    const scrollRef = useRef<HTMLDivElement>(null)

    useEffect(() => {
        if (remoteStream && videoRef.current) {
            videoRef.current.srcObject = remoteStream
        }
    }, [remoteStream])

    useEffect(() => {
        const fetchDetails = async () => {
            try {
                const response = await api.get(`/interviews/${interviewId}`)
                setInterview(response.data)
                setMessages(response.data.transcript || [])
            } catch (error) {
                console.error("Failed to fetch interview details", error)
                toast.error("Cloud not find this interview session")
            } finally {
                setLoading(false)
            }
        }

        fetchDetails()

        let activeSocket: any = null
        let isMounted = true

        const connectSocket = async () => {
            const token = await getFreshToken()
            if (!isMounted) return

            const baseUrl = (process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3003').replace(/\/api$/, '')
            activeSocket = io(`${baseUrl}/recruiter-monitor`, {
                auth: { token },
                transports: ['websocket']
            })

            activeSocket.on('connect', () => {
                console.log('Socket: Connected as recruiter')
                activeSocket.emit('join-room', { interviewId, role: 'recruiter' })
            })

            activeSocket.on('candidate-offer', async (data: any) => {
                console.log('Socket: Received offer from candidate')
                const pc = new RTCPeerConnection({
                    iceServers: [{ urls: 'stun:stun.l.google.com:19302' }]
                })

                pc.ontrack = (event) => {
                    console.log('WebRTC: Received remote track', event.streams[0])
                    setRemoteStream(event.streams[0])
                }

                pc.onicecandidate = (event) => {
                    if (event.candidate) {
                        activeSocket.emit('ice-candidate', { interviewId, candidate: event.candidate })
                    }
                }

                await pc.setRemoteDescription(new RTCSessionDescription(data.offer))
                const answer = await pc.createAnswer()
                await pc.setLocalDescription(answer)

                activeSocket.emit('recruiter-answer', { interviewId, answer })
                setPeerConnection(prev => {
                    if (prev) prev.close()
                    return pc
                })
            })

            activeSocket.on('ice-candidate', async (data: any) => {
                setPeerConnection(pc => {
                    if (pc) pc.addIceCandidate(new RTCIceCandidate(data.candidate)).catch(console.error)
                    return pc
                })
            })

            activeSocket.on('interview:question', (data: any) => {
                setMessages(prev => [...prev, { speaker: 'AI', message: msgText(data), timestamp: new Date() }])
            })

            activeSocket.on('interview:answer', (data: any) => {
                setMessages(prev => [...prev, { speaker: 'Candidate', message: msgText(data), timestamp: new Date() }])
            })

            activeSocket.on('interview:status', (data: any) => {
                if (data.status === 'completed' || data.status === 'terminated' || data.status === 'FAILED_INTERVIEW') {
                    toast.info(`Interview has ended: ${data.status}`)
                    setTimeout(() => router.push('/recruiter/interviews'), 2000)
                }
            })

            setSocket(activeSocket)
        }

        const msgText = (data: any) => data.text || data.question || data.answer || ""

        connectSocket()

        return () => {
            isMounted = false
            if (activeSocket) activeSocket.disconnect()
            setPeerConnection(pc => {
                if (pc) pc.close()
                return null
            })
        }
    }, [interviewId])

    useEffect(() => {
        if (scrollRef.current) {
            scrollRef.current.scrollIntoView({ behavior: "smooth" })
        }
    }, [messages])

    const handleTerminate = async () => {
        if (!confirm("Are you sure you want to manually end this interview?")) return
        setIsTerminating(true)
        try {
            await api.post(`/interview-agent/${interviewId}/terminate`, {
                reason: 'RECRUITER_MANUAL_TERMINATION',
                message: 'This interview has been ended by the recruiter. You will be redirected shortly.'
            })
            toast.success("Interview terminated session")
            router.push('/recruiter/interviews')
        } catch (error) {
            console.error("Failed to terminate", error)
            toast.error("Failed to terminate interview")
        } finally {
            setIsTerminating(false)
        }
    }

    if (loading) return (
        <div className="flex h-screen items-center justify-center bg-slate-900">
            <Loader2 className="h-8 w-8 animate-spin text-primary" />
        </div>
    )

    return (
        <div className="flex flex-col h-screen bg-[#0a0f1c] text-slate-200">
            {/* Top Navigation Bar */}
            <header className="h-20 border-b border-white/5 flex items-center justify-between px-8 bg-[#0a0f1c]/80 backdrop-blur-xl sticky top-0 z-50">
                <div className="flex items-center gap-6">
                    <Button variant="ghost" size="icon" onClick={() => router.back()} className="rounded-2xl hover:bg-white/5 text-slate-400">
                        <X size={20} />
                    </Button>
                    <div className="flex flex-col">
                        <div className="flex items-center gap-3">
                            <h1 className="text-xl font-bold tracking-tight">Live Interview Monitor</h1>
                            <Badge className="bg-red-500/10 text-red-500 border-red-500/20 rounded-full flex items-center gap-1.5 px-3 py-1 animate-pulse">
                                <div className="w-1.5 h-1.5 bg-red-500 rounded-full" />
                                LIVE
                            </Badge>
                        </div>
                        <p className="text-xs text-slate-500 font-medium">Session ID: {interviewId}</p>
                    </div>
                </div>

                <div className="flex items-center gap-4">
                    <div className="flex items-center gap-2 px-4 py-2 bg-white/5 rounded-2xl border border-white/10">
                        <Signal size={14} className="text-green-500" />
                        <span className="text-xs font-bold text-slate-400">Stable Connection</span>
                    </div>
                    <Button
                        variant="destructive"
                        onClick={handleTerminate}
                        disabled={isTerminating}
                        className="rounded-2xl h-12 px-6 bg-red-600 hover:bg-red-700 font-bold shadow-xl shadow-red-900/20 flex gap-2"
                    >
                        {isTerminating ? <Loader2 className="animate-spin h-4 w-4" /> : <Power size={18} />}
                        Terminate Interview
                    </Button>
                </div>
            </header>

            <main className="flex-1 flex overflow-hidden">
                {/* Left Side: Video & Stats */}
                <div className="flex-1 p-8 flex flex-col gap-6 overflow-y-auto">
                    {/* Live Stream Card */}
                    <Card className="border-none shadow-2xl rounded-[2.5rem] bg-black overflow-hidden aspect-video relative ring-1 ring-white/10">
                        {!remoteStream && (
                            <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-900/50 backdrop-blur-sm z-10">
                                <Video size={64} className="text-slate-700 mb-4 animate-pulse" />
                                <p className="text-slate-500 font-bold">Waiting for candidate video stream...</p>
                            </div>
                        )}
                        <video
                            ref={videoRef}
                            autoPlay
                            playsInline
                            className="w-full h-full object-cover"
                        />
                        <div className="absolute bottom-8 left-8 flex items-center gap-3">
                            <div className="px-4 py-2 rounded-2xl bg-black/40 backdrop-blur-md border border-white/20 flex items-center gap-3">
                                <div className="w-2 h-2 bg-green-500 rounded-full shadow-[0_0_10px_rgba(34,197,94,0.5)]" />
                                <span className="text-[10px] font-bold uppercase tracking-wider text-white">
                                    Candidate Active
                                </span>
                            </div>
                        </div>
                    </Card>

                    {/* Meta Info Grid */}
                    <div className="grid md:grid-cols-3 gap-6">
                        <Card className="border-none shadow-sm rounded-3xl bg-white/5 border border-white/10 p-6">
                            <div className="flex items-center gap-4 mb-4">
                                <div className="p-3 bg-blue-500/10 rounded-2xl">
                                    <User size={20} className="text-blue-500" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">Candidate</p>
                                    <p className="font-bold text-white">{interview?.candidate?.user?.firstName} {interview?.candidate?.user?.lastName}</p>
                                </div>
                            </div>
                        </Card>
                        <Card className="border-none shadow-sm rounded-3xl bg-white/5 border border-white/10 p-6">
                            <div className="flex items-center gap-4 mb-4">
                                <div className="p-3 bg-purple-500/10 rounded-2xl">
                                    <ShieldAlert size={20} className="text-purple-500" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">Role</p>
                                    <p className="font-bold text-white">{interview?.job?.title}</p>
                                </div>
                            </div>
                        </Card>
                        <Card className="border-none shadow-sm rounded-3xl bg-white/5 border border-white/10 p-6">
                            <div className="flex items-center gap-4 mb-4">
                                <div className="p-3 bg-orange-500/10 rounded-2xl">
                                    <Clock size={20} className="text-orange-500" />
                                </div>
                                <div>
                                    <p className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">Elapsed Time</p>
                                    <p className="font-bold text-white">Live Session</p>
                                </div>
                            </div>
                        </Card>
                    </div>
                </div>

                {/* Right Side: Live Transcript */}
                <aside className="w-[450px] border-l border-white/5 bg-[#0a0f1c] flex flex-col">
                    <div className="p-8 border-b border-white/5 flex items-center justify-between">
                        <div className="flex items-center gap-3">
                            <div className="p-2.5 bg-blue-500/10 rounded-xl">
                                <MessageSquare size={18} className="text-blue-500" />
                            </div>
                            <h2 className="font-bold text-lg text-white">Live Transcript</h2>
                        </div>
                        <Badge variant="outline" className="rounded-full border-white/10 text-slate-400">Real-time sync</Badge>
                    </div>

                    <div className="flex-1 overflow-y-auto p-8 pb-32">
                        <div className="space-y-8">
                            {messages.length === 0 ? (
                                <div className="flex flex-col items-center justify-center p-20 text-center space-y-4 opacity-30">
                                    <MessageSquare size={40} />
                                    <p className="text-sm font-medium">Listening for live dialogue...</p>
                                </div>
                            ) : (
                                messages.map((msg, i) => (
                                    <motion.div
                                        key={i}
                                        initial={{ opacity: 0, x: msg.speaker === 'Candidate' ? 20 : -20 }}
                                        animate={{ opacity: 1, x: 0 }}
                                        className={`flex flex-col ${msg.speaker === 'Candidate' ? 'items-end' : 'items-start'}`}
                                    >
                                        <div className="flex items-center gap-2 mb-2">
                                            <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest px-2">
                                                {msg.speaker === 'AI' ? 'Alex (Interviewer)' : 'Candidate'}
                                            </span>
                                        </div>
                                        <div className={`max-w-[85%] p-4 rounded-3xl text-sm leading-relaxed ${msg.speaker === 'Candidate'
                                            ? 'bg-blue-600 text-white rounded-tr-none shadow-xl shadow-blue-900/20'
                                            : 'bg-white/5 border border-white/10 text-slate-300 rounded-tl-none'
                                            }`}>
                                            {msg.message}
                                        </div>
                                    </motion.div>
                                ))
                            )}
                            <div ref={scrollRef} />
                        </div>
                    </div>
                </aside>
            </main>
        </div>
    )
}

"use client"

import { useEffect, useState } from "react";
import { AIAnalyticsCharts } from "@/components/dashboard/AIAnalyticsCharts";
import { MetricCard } from "@/components/dashboard/MetricCard";
import { RecentCandidates } from "@/components/dashboard/RecentCandidates";
import { Users, Video, Brain, TrendingUp, Loader2 } from "lucide-react";
import LiveInterviews from "@/components/dashboard/LiveInterviews";
import { motion } from "framer-motion";
